// We cannot export it from @iobroker/adapter-core as this file is used in tests
enum EXIT_CODES {
    ADAPTER_REQUESTED_TERMINATION = 11, // planned stop
}

// todo delete from persistentSessions the sessions and messages after some time
type HttpHttpsServer = HttpsServer | HttpServer;
type Server = TlsServer | NetServer;
type MqttMessage = {
    topic: string;
    /** MQTT 5 properties of an outgoing PUBLISH (subscription identifier, message expiry, ...) */
    properties?: Record<string, any>;
    /** When this message stops being deliverable (MQTT 5 message expiry), absolute time in ms */
    expiresAt?: number;
    payload: string | null;
    qos: 0 | 1 | 2;
    retain: boolean;
    messageId: number;
    ts?: number;
    count?: number;
    cmd?: 'pubreq' | 'publish' | 'pubrel';
    dup?: boolean;
    binary?: boolean;
};

/**
 * One subscription of a client.
 *
 * `nl`, `rap` and `rh` are the MQTT 5 subscription options (MQTT-5.0 3.8.3.1). They are absent for
 * MQTT 3.1.1 clients, where the defaults (send everything, force our own retain flag, always send
 * the known value on subscribe) match the behaviour the adapter always had.
 */
type MqttSubscription = {
    regex: RegExp;
    qos: 0 | 1 | 2;
    pattern: MqttPattern;
    /** No Local: do not send a message back to the client that published it */
    nl?: boolean;
    /** Retain As Published: forward the retain flag of the incoming message instead of ours */
    rap?: boolean;
    /** Retain Handling: 0/1 = send the known value on subscribe, 2 = do not */
    rh?: 0 | 1 | 2;
    /** MQTT 5 subscription identifier, echoed back on every message this subscription matches */
    subscriptionIdentifier?: number;
    /** MQTT 5 share name when this came from a "$share/<name>/<filter>" subscription */
    shareName?: string;
};

interface PersistentSession {
    id: string;
    _subsID?: Record<string, MqttSubscription>;
    _subs?: Record<string, MqttSubscription>;
    _messages: MqttMessage[];
    connected?: boolean;
    lastSeen: number;
}

/**
 * A connection plus the per-client bookkeeping the broker attaches to it: its id, the pending
 * QoS 1/2 messages, its subscriptions and its session flags.
 */
type MqttClientConnection = MqttConnection & {
    id: string;
    _messages: MqttMessage[];
    _sendOnStart?: NodeJS.Timeout | null;
    _resendonStart?: NodeJS.Timeout | null;
    __secret?: string;
    _will: {
        topic: string;
        payload: string;
        qos: 0 | 1 | 2;
        retain: boolean;
    };
    _subsID?: Record<string, MqttSubscription>;
    _subs?: Record<string, MqttSubscription>;
    cleanSession?: boolean;
    _keepalive: number;
    authenticated?: boolean;
    /** MQTT 5 topic aliases the client established on this connection (alias to topic) */
    _topicAliases?: Map<number, MqttTopic>;
    /** MQTT 5 session expiry interval in seconds, 0 = end the session with the connection */
    _sessionExpiryInterval?: number;
    /** MQTT 5 will delay interval in seconds, 0 = publish the will as soon as the connection drops */
    _willDelayInterval?: number;
    /** MQTT 5 "Receive Maximum": how many QoS > 0 messages may be in flight to this client */
    _receiveMaximum?: number;
    /** Messages that have to wait because the client's receive maximum is exhausted */
    _pendingMessages?: MqttMessage[];
    /** MQTT 5 enhanced authentication method this connection agreed on */
    _authMethod?: string;
    /** The running SCRAM exchange, while the client is still proving who it is */
    _scram?: ScramExchange;
    /** What to run once the enhanced authentication succeeded */
    _completeConnect?: () => void;
    /** The SCRAM server-final message, which travels back in the CONNACK */
    _scramServerFinal?: Buffer;
};

const messageboxRegex = new RegExp('\\.messagebox$');

/**
 * How many MQTT 5 topic aliases a client may use. Announced in the CONNACK; a client must not use
 * an alias above this value, and none at all if we announce 0 (MQTT-5.0 3.1.2.11.3).
 */
const TOPIC_ALIAS_MAXIMUM = 32;

/**
 * How long a state change is still attributed to the client that published it, so a "No Local"
 * subscriber does not get its own message back through the state change fan-out.
 */
const NO_LOCAL_WINDOW = 2000;

/**
 * Why a message is sent to a client.
 *
 * `retained` means it is the value the broker already had and delivers because a subscription was
 * just established ("Publish own states on connect"); `live` means it is forwarded as it happens.
 * MQTT 5 wants a different RETAIN flag for the two (MQTT-5.0 3.8.3.1 / 3.8.4).
 */
type MessageDelivery = 'live' | 'retained';

/** Anything that carries subscriptions: a connected client or a stored offline session. */
type Subscriber = {
    _subsID?: Record<string, MqttSubscription>;
    _subs?: Record<string, MqttSubscription>;
};

/** The part of an incoming PUBLISH the topic alias handling needs. */
type IncomingPublish = {
    topic: string;
    properties?: { topicAlias?: number };
};

export default class MQTTServer {
    private readonly adapter: ioBroker.Adapter;
    private readonly config: MqttAdapterConfig;
    private readonly namespaceRegEx: RegExp;
    private server: Server | null = null;
    private serverWs: WsServer | null = null;
    private serverForWs: HttpHttpsServer | null = null;
    private readonly clients: { [clientID: string]: MqttClientConnection } = {};
    private readonly topic2id: Record<
        MqttTopic,
        {
            processing?: boolean;
            obj: ioBroker.StateObject | null;
            id: string;
            isAck?: boolean;
            message?:
                | { message: string | number | boolean | Record<string, any>; isStateObject: false }
                | { message: ioBroker.State; isStateObject: true };
        }
    > = {};
    private readonly id2topic: Record<string, MqttTopic> = {};
    // Topics for which `resolveTopicId` already scanned the published states, so the scan runs
    // at most once per topic.
    private readonly resolvedTopics: Record<MqttTopic, true> = {};
    // Which client last published a state and when. `onStateChange` fans a state change out to
    // every client without knowing where it came from, so the MQTT 5 "No Local" option needs this
    // to recognise the publisher. Entries are only consulted for a short moment (see NO_LOCAL_WINDOW).
    private readonly lastPublisher: Record<string, { secret: string; ts: number }> = {};
    // Wills whose "Will Delay Interval" has not passed yet, keyed by client id. A client that comes
    // back within the delay cancels its own will (MQTT-5.0 3.1.3.2.2).
    private readonly delayedWills: Record<string, ioBroker.Timeout | undefined> = {};
    // When the value of a state stops being deliverable, from the MQTT 5 "Message Expiry Interval"
    // of the publish that produced it (MQTT-5.0 3.3.2.3.3). Absent means it never expires.
    private readonly messageExpiry: Record<string, number> = {};
    // MQTT 5 shared subscriptions (MQTT-5.0 4.8.2). Every group delivers a matching message to
    // exactly one of its members, so the choice cannot be made per client and lives here.
    // Salt and derived key for SCRAM. The salt is generated once per adapter start and the
    // expensive derivation is done on first use only, so authenticating stays cheap.
    private readonly scramSalt = createSalt();
    private scramSaltedPassword: Promise<Buffer> | null = null;
    private readonly sharedGroups: Record<
        string,
        { shareName: string; pattern: MqttPattern; regex: RegExp; members: string[]; cursor: number }
    > = {};
    private messageId = 1;
    private persistentSessions: {
        [clientId: string]: PersistentSession;
    } = {};
    private resending = false;
    private resendTimer: NodeJS.Timeout | null = null;
    private readonly verifiedObjects = {};
    private updateClientsTimeout: ioBroker.Timeout | undefined;
    private updateClientsRunning = false;
    private updateClientsRestart = false;

    private readonly ignoredTopicsRegexes: RegExp[] = [];
    private readonly ignoredTopics: string[] = [];
    private readonly binaryTopicsRegexes: RegExp[] = [];
    private readonly binaryTopics: string[] = [];
    private readonly states: Record<string, ioBroker.State>;

    constructor(adapter: ioBroker.Adapter, states: Record<string, ioBroker.State>) {
        this.adapter = adapter;
        this.config = adapter.config as MqttAdapterConfig;
        this.namespaceRegEx = new RegExp(`^${this.adapter.namespace.replace('.', '\\.')}\\.`);
        this.ignoredTopics = this.config.ignoredTopics?.split(',') ?? [];
        this.states = states;

        for (const ignoredTopicPattern of this.ignoredTopics) {
            if (!ignoredTopicPattern) {
                // Empty strings would filter out all topics, which is probably not what the user wants
                this.ignoredTopics.length > 1 && this.adapter.log.warn(`Ignored topics should not end with an ",".`);
                continue;
            }
            const ignoredTopicRegexWithNameSpace = pattern2RegEx(
                `${this.adapter.namespace}.${ignoredTopicPattern}`,
                adapter,
                this.config.prefix,
                this.config.dotToUnderscore,
            );
            const ignoredTopicRegex = pattern2RegEx(
                ignoredTopicPattern,
                adapter,
                this.config.prefix,
                this.config.dotToUnderscore,
            );
            this.adapter.log.info(
                `Ignoring topic with pattern: ${ignoredTopicPattern} (RegExp: ${ignoredTopicRegex} und ${ignoredTopicRegexWithNameSpace})`,
            );
            this.ignoredTopicsRegexes.push(new RegExp(ignoredTopicRegex), new RegExp(ignoredTopicRegexWithNameSpace));
        }

        this.binaryTopics = this.config.binaryTopics?.split(',') ?? [];
        for (const binaryTopicPattern of this.binaryTopics) {
            if (!binaryTopicPattern) {
                continue;
            }
            const binaryTopicRegexWithNameSpace = pattern2RegEx(
                `${this.adapter.namespace}.${binaryTopicPattern}`,
                adapter,
                this.config.prefix,
                this.config.dotToUnderscore,
            );
            const binaryTopicRegex = pattern2RegEx(
                binaryTopicPattern,
                adapter,
                this.config.prefix,
                this.config.dotToUnderscore,
            );
            this.adapter.log.info(
                `Storing topic as file with pattern: ${binaryTopicPattern} (RegExp: ${binaryTopicRegex} und ${binaryTopicRegexWithNameSpace})`,
            );
            this.binaryTopicsRegexes.push(new RegExp(binaryTopicRegex), new RegExp(binaryTopicRegexWithNameSpace));
        }

        this.config.sendOnStartInterval = parseInt(this.config.sendOnStartInterval as unknown as string, 10) || 2000;
        this.config.sendInterval = parseInt(this.config.sendInterval as unknown as string, 10) || 0;
        this.init();
    }

    destroy(cb?: () => void): void {
        if (this.resendTimer) {
            clearInterval(this.resendTimer);
            this.resendTimer = null;
        }
        // pending wills must not fire into a torn down adapter
        for (const clientId of Object.keys(this.delayedWills)) {
            this.adapter.clearTimeout(this.delayedWills[clientId]);
            delete this.delayedWills[clientId];
        }
        this.persistentSessions = {};

        let tasks = 0;
        let timeout: NodeJS.Timeout | null = null;
        if (cb) {
            timeout = setTimeout(() => {
                timeout = null;
                if (cb) {
                    cb();
                    cb = undefined;
                }
            }, 2000);
        }
        if (this.server) {
            tasks++;
            // to release all resources
            this.server.close(() => {
                console.log('all gone!');
                if (!--tasks && cb) {
                    if (timeout) {
                        clearTimeout(timeout);
                        timeout = null;
                    }
                    cb();
                    cb = undefined;
                }
            });
            this.server = null;
        }

        if (this.serverForWs) {
            tasks++;
            // to release all resources
            this.serverForWs.close(() => {
                console.log('all ws gone!');
                if (!--tasks && cb) {
                    if (timeout) {
                        clearTimeout(timeout);
                        timeout = null;
                    }
                    cb();
                    cb = undefined;
                }
            });
            this.serverForWs = null;
        }
        if (!tasks && cb) {
            if (timeout) {
                clearTimeout(timeout);
                timeout = null;
            }
            cb();
            cb = undefined;
        }
    }

    onMessage(topic: MqttTopic, message: any, retain: boolean, binary?: boolean): void {
        if (this.server) {
            setImmediate(() => {
                for (const k in this.clients) {
                    if (Object.prototype.hasOwnProperty.call(this.clients, k)) {
                        this.sendMessage2Client(this.clients[k], topic, message, retain ?? this.config.retain, binary);
                    }
                }

                /*
                for (let clientId in persistentSessions) {
                    if (persistentSessions.hasOwnProperty(clientId) && !this.clients[clientId]) {
                        (function (_clientId) {
                            getMqttMessage(persistentSessions[_clientId], id, state, this.config.defaultQoS, true, (err, message) => {
                                message && persistentSessions[_clientId]._messages.push(message);
                            });
                        })(clientId);
                    }
                }
                */
            });
        }
    }

    onStateChange(id: string, state: ioBroker.State | null | undefined): void {
        this.adapter.log.debug(`onStateChange ${id}: ${JSON.stringify(state)}`);

        if (!this.server) {
            return;
        }

        setImmediate(() => {
            const sharedRecipients = this.resolveSharedRecipients(id);

            Object.keys(this.clients).forEach(k => {
                if (this.publishedItself(this.clients[k], id)) {
                    return;
                }
                if (!this.isRecipient(this.clients[k], id, sharedRecipients)) {
                    return;
                }
                this.sendState2Client(this.clients[k], id, state, this.config.defaultQoS, !this.config.noRetain);
            });

            Object.keys(this.persistentSessions).forEach(clientId => {
                if (!this.clients[clientId]) {
                    this.getMqttMessage<PersistentSession>(
                        this.persistentSessions[clientId],
                        id,
                        state,
                        this.config.defaultQoS,
                        !this.config.noRetain,
                        (_err, message, persistentClient) =>
                            message &&
                            persistentClient &&
                            this.addMessageWithTopicCheck(persistentClient._messages, message),
                    );
                }
            });
        });
    }

    private async updateClientObjects(): Promise<void> {
        if (this.config.doNotCreateClientObjects) {
            return;
        }
        if (this.updateClientsRunning) {
            this.updateClientsRestart = true;
            return;
        }
        this.updateClientsRunning = true;
        try {
            const clientIds = [];

            if (this.clients) {
                for (const id in this.clients) {
                    const _id = id || this.clients[id]?.id || this.clients[id]?.stream?.remoteAddress;
                    const oid = `info.clients.${_id.replace(/[.\s]+/g, '_')}`;
                    clientIds.push(oid);
                    const clientObj = await this.adapter.getObjectAsync(oid);
                    if (!clientObj?.native) {
                        await this.adapter.setObject(oid, {
                            type: 'state',
                            common: {
                                name: _id,
                                role: 'indicator.reachable',
                                type: 'boolean',
                                read: true,
                                write: false,
                            },
                            native: {
                                ip: this.clients[id]?.stream?.remoteAddress,
                                port: this.clients[id]?.stream?.remotePort,
                            },
                        });
                    } else if (
                        clientObj.native.port !== this.clients[id]?.stream?.remotePort ||
                        clientObj.native.ip !== this.clients[id]?.stream?.remoteAddress
                    ) {
                        clientObj.native.port = this.clients[id]?.stream?.remotePort;
                        clientObj.native.ip = this.clients[id]?.stream?.remoteAddress;
                        await this.adapter.setObjectAsync(clientObj._id, clientObj);
                    }
                    await this.adapter.setStateAsync(oid, true, true);
                }
            }

            // read all other states and set alive to false
            const allStates = await this.adapter.getStatesAsync('info.clients.*');
            for (const id in allStates) {
                if (!clientIds.includes(id.replace(`${this.adapter.namespace}.`, ''))) {
                    await this.adapter.setState(id, false, true);
                }
            }
        } finally {
            this.updateClientsRunning = false;
        }

        if (this.updateClientsRestart) {
            this.updateClientsRestart = false;
            this.startUpdateClientObjects();
        }
    }

    private startUpdateClientObjects(): void {
        if (this.updateClientsTimeout) {
            this.adapter.clearTimeout(this.updateClientsTimeout);
            this.updateClientsTimeout = undefined;
        }
        this.updateClientsRestart = false;
        this.updateClientsTimeout = this.adapter.setTimeout(() => {
            this.updateClientObjects().catch(e => this.adapter.log.error(`Cannot update client objects: ${e}`));
        }, 1000);
    }

    private updateClients(): void {
        this.startUpdateClientObjects();

        void this.adapter.setState('info.connection', {
            val: this.clients ? Object.keys(this.clients).join(', ') : '',
            ack: true,
        });
    }

    /**
     * Decides whether a state change may be forwarded to a client.
     *
     * `extraSet` normally lets the publisher receive its own message back, because "get" and "set"
     * then use different topics. An MQTT 5 client that subscribed with the "No Local" option has
     * explicitly asked not to get its own messages, and that wins (MQTT-5.0 3.8.3.1).
     *
     * @param client The client the message would be sent to
     * @param ignoreClient The client the message came from
     * @param id The state id that changed
     * @returns Whether the message may be sent
     */
    private mayReceiveOwnMessage(
        client: MqttClientConnection,
        ignoreClient: MqttClientConnection,
        id: string,
    ): boolean {
        if (client !== ignoreClient) {
            return true;
        }
        if (!this.config.extraSet) {
            return false;
        }
        return !this.isNoLocal(client, id);
    }

    /**
     * Adds a client to a shared subscription group, creating the group if it is new.
     *
     * @param shareName The share name from "$share/<name>/<filter>"
     * @param pattern The ioBroker pattern the filter was converted to
     * @param regex The compiled pattern, used to decide which messages the group receives
     * @param clientId The subscribing client
     */
    /**
     * Converts a topic filter into the ioBroker pattern a shared subscription group is keyed by.
     *
     * The group must be identified by the filter the clients subscribed to, not by the state id it
     * happens to resolve to: the first subscriber of a topic sees the unresolved id and a later one
     * the created object, which would put members of the same group into two different ones.
     *
     * @param filter The topic filter, already without the "$share/<name>/" prefix
     * @returns The pattern used as the group key and for its regex
     */
    private sharedPatternFor(filter: MqttTopic): MqttPattern {
        let pattern = filter;
        if (this.config.prefix && pattern.startsWith(this.config.prefix)) {
            pattern = pattern.substring(this.config.prefix.length);
        }
        pattern = pattern.replace(/\//g, '.');
        if (pattern[0] === '.') {
            pattern = pattern.substring(1);
        }
        return pattern;
    }

    private joinSharedGroup(shareName: string, pattern: MqttPattern, regex: RegExp, clientId: string): void {
        const key = JSON.stringify([shareName, pattern]);
        this.sharedGroups[key] ||= { shareName, pattern, regex, members: [], cursor: 0 };

        if (!this.sharedGroups[key].members.includes(clientId)) {
            this.sharedGroups[key].members.push(clientId);
        }
        this.adapter.log.info(
            `Client [${clientId}] joined shared subscription "${shareName}" for "${pattern}" ` +
                `(${this.sharedGroups[key].members.length} member(s))`,
        );
    }

    /**
     * Removes a client from shared subscription groups. Empty groups are dropped.
     *
     * @param clientId The client to remove
     * @param pattern Only leave the groups for this pattern; all of them when undefined
     */
    private leaveSharedGroups(clientId: string, pattern?: MqttPattern): void {
        for (const key of Object.keys(this.sharedGroups)) {
            const group = this.sharedGroups[key];
            if (pattern !== undefined && group.pattern !== pattern) {
                continue;
            }
            const index = group.members.indexOf(clientId);
            if (index !== -1) {
                group.members.splice(index, 1);
                if (group.cursor > index) {
                    group.cursor--;
                }
            }
            if (!group.members.length) {
                delete this.sharedGroups[key];
            }
        }
    }

    /**
     * Picks which clients receive a message through a shared subscription.
     *
     * Every group that matches the state gets exactly one recipient, chosen round robin over its
     * connected members. A client that is in several matching groups is picked once per group,
     * which is what the standard asks for — the groups are independent of each other.
     *
     * @param id The state id that changed
     * @returns The ids of the clients that were drawn
     */
    private resolveSharedRecipients(id: string): Set<string> {
        const chosen = new Set<string>();

        for (const key of Object.keys(this.sharedGroups)) {
            const group = this.sharedGroups[key];
            if (!group.regex.test(id)) {
                continue;
            }

            // skip members that are not connected right now
            const available = group.members.filter(clientId => this.clients[clientId]);
            if (!available.length) {
                continue;
            }

            group.cursor = (group.cursor + 1) % available.length;
            chosen.add(available[group.cursor]);
        }

        return chosen;
    }

    /**
     * Decides whether a client may receive a message at all.
     *
     * A normal subscription always delivers. A shared subscription only delivers to the member that
     * was drawn for this message, so a client that lost the draw and has no other matching
     * subscription is skipped.
     *
     * @param client The client in question
     * @param id The state id that changed
     * @param sharedRecipients The clients drawn for this message
     * @returns Whether the message may be sent to this client
     */
    private isRecipient(client: MqttClientConnection, id: string, sharedRecipients: Set<string>): boolean {
        if (sharedRecipients.has(client.id)) {
            return true;
        }
        return this.hasUnsharedMatch(client, id);
    }

    /**
     * Checks whether a client has a normal (not shared) subscription matching a state.
     *
     * @param client The client
     * @param id The state id
     * @returns Whether a normal subscription matches
     */
    private hasUnsharedMatch(client: Subscriber, id: string): boolean {
        if (client._subsID?.[id]) {
            return !client._subsID[id].shareName;
        }
        if (client._subs) {
            for (const topic of Object.keys(client._subs)) {
                if (client._subs[topic].regex.test(id) && !client._subs[topic].shareName) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Sends one message to a client, honouring its MQTT 5 "Receive Maximum".
     *
     * A client may limit how many QoS 1/2 messages the broker has unacknowledged at any time
     * (MQTT-5.0 4.9). Anything above the limit has to wait instead of being sent, otherwise the
     * client is entitled to close the connection with a protocol error. QoS 0 does not count.
     *
     * @param client The receiving client
     * @param message The message to send
     */
    private deliver(client: MqttClientConnection, message: MqttMessage): void {
        if (!message.qos) {
            client.publish(message);
            return;
        }

        client._messages ||= [];

        const limit = client._receiveMaximum;
        if (limit && this.inFlightCount(client) >= limit) {
            client._pendingMessages ||= [];
            client._pendingMessages.push(message);
            this.adapter.log.debug(
                `Client [${client.id}] receive maximum (${limit}) reached, "${message.topic}" has to wait`,
            );
            return;
        }

        client.publish(message);
        client._messages.push(message);
    }

    /**
     * Counts the QoS 1/2 messages the broker sent to a client and that are still unacknowledged.
     * Inbound QoS 2 packets waiting for a PUBREL are stored in the same list but do not count.
     *
     * @param client The client
     * @returns The number of messages in flight
     */
    private inFlightCount(client: MqttClientConnection): number {
        return client._messages?.filter(message => message.cmd === 'publish').length ?? 0;
    }

    /**
     * Sends what had to wait for the client's receive maximum, called whenever a slot became free.
     *
     * @param client The client that just acknowledged a message
     */
    private flushPending(client: MqttClientConnection): void {
        const limit = client._receiveMaximum;
        if (!limit || !client._pendingMessages?.length) {
            return;
        }

        while (client._pendingMessages.length && this.inFlightCount(client) < limit) {
            const message = client._pendingMessages.shift()!;
            if (message.expiresAt && message.expiresAt <= Date.now()) {
                this.adapter.log.debug(`Client [${client.id}] Queued message for "${message.topic}" expired`);
                continue;
            }
            message.ts = Date.now();
            client.publish(message);
            client._messages.push(message);
        }
    }

    /**
     * Builds the MQTT 5 properties of an outgoing PUBLISH.
     *
     * Currently that is the subscription identifier, which tells the client which of its
     * subscriptions matched (MQTT-5.0 3.3.4). MQTT 3.1.1 clients get no properties at all.
     *
     * @param client The receiving client
     * @param id The state id
     * @returns The properties, or undefined when there is nothing to send
     */
    private outgoingProperties(client: Subscriber, id: string): Record<string, any> | undefined {
        if ((client as { protocolVersion?: number }).protocolVersion !== 5) {
            return undefined;
        }

        const properties: Record<string, any> = {};

        const subscriptionIdentifier = this.findSubscription(client, id)?.subscriptionIdentifier;
        if (subscriptionIdentifier) {
            properties.subscriptionIdentifier = subscriptionIdentifier;
        }

        // What is left of the publisher's "Message Expiry Interval" — the standard wants the value
        // it was published with minus the time it waited here (MQTT-5.0 3.3.2.3.3).
        const remaining = this.remainingExpiry(id);
        if (remaining !== undefined) {
            properties.messageExpiryInterval = remaining;
        }

        return Object.keys(properties).length ? properties : undefined;
    }

    /**
     * Checks whether the value of a state may still be delivered.
     *
     * @param id The state id
     * @returns Whether its message expiry interval has passed
     */
    private isExpired(id: string): boolean {
        const expiresAt = this.messageExpiry[id];
        if (!expiresAt) {
            return false;
        }
        if (expiresAt > Date.now()) {
            return false;
        }
        delete this.messageExpiry[id];
        return true;
    }

    /**
     * Calculates how many seconds a value may still be delivered.
     *
     * @param id The state id
     * @returns The remaining seconds, or undefined when it never expires or already did
     */
    private remainingExpiry(id: string): number | undefined {
        const expiresAt = this.messageExpiry[id];
        if (!expiresAt) {
            return undefined;
        }
        const remaining = Math.ceil((expiresAt - Date.now()) / 1000);
        return remaining > 0 ? remaining : undefined;
    }

    /**
     * Determines the RETAIN flag of an outgoing message.
     *
     * MQTT 3.1.1 clients keep what the adapter always did: the flag comes from the
     * `Publish messages without "retain" flag` setting, because every value is stored in the
     * States DB and a reconnecting client should find it.
     *
     * MQTT 5 defines it per subscription (MQTT-5.0 3.8.3.1): a message delivered because the
     * subscription was just established is retained, everything forwarded afterwards carries
     * RETAIN 0 — unless the client asked for "Retain As Published", then it keeps the flag the
     * message was published with.
     *
     * @param client The receiving client (or an offline session, which is never MQTT 5)
     * @param id The state id
     * @param retain The flag the message was published with
     * @param delivery Whether this is retained delivery or a live forward
     * @returns The RETAIN flag to put on the wire
     */
    private effectiveRetain(client: Subscriber, id: string, retain: boolean, delivery: MessageDelivery): boolean {
        if ((client as { protocolVersion?: number }).protocolVersion !== 5) {
            return retain;
        }
        if (delivery === 'retained') {
            return true;
        }
        return this.findSubscription(client, id)?.rap ? retain : false;
    }

    /**
     * Finds the subscription of a client that matches a state id.
     *
     * @param client The subscribing client
     * @param id The state id
     * @returns The matching subscription, or undefined if there is none
     */
    private findSubscription(client: Subscriber, id: string): MqttSubscription | undefined {
        if (client._subsID?.[id]) {
            return client._subsID[id];
        }
        if (client._subs) {
            for (const topic of Object.keys(client._subs)) {
                if (client._subs[topic].regex.test(id)) {
                    return client._subs[topic];
                }
            }
        }
        return undefined;
    }

    /**
     * Checks whether this client just published the state itself and subscribed with "No Local",
     * so the state change must not be sent back to it.
     *
     * @param client The client the message would be sent to
     * @param id The state id that changed
     * @returns Whether the message has to be suppressed for this client
     */
    private publishedItself(client: MqttClientConnection, id: string): boolean {
        const publisher = this.lastPublisher[id];
        if (!publisher || !client.__secret || publisher.secret !== client.__secret) {
            return false;
        }
        if (Date.now() - publisher.ts > NO_LOCAL_WINDOW) {
            delete this.lastPublisher[id];
            return false;
        }
        return this.isNoLocal(client, id);
    }

    /**
     * Checks whether the subscription that matches `id` was made with the MQTT 5 "No Local" option.
     *
     * @param client The subscribing client
     * @param id The state id
     * @returns Whether the client asked not to receive its own messages for this topic
     */
    private isNoLocal(client: MqttClientConnection, id: string): boolean {
        return !!this.findSubscription(client, id)?.nl;
    }

    /**
     * Applies the MQTT 5 topic alias of an incoming PUBLISH (MQTT-5.0 3.3.2.3.4).
     *
     * A packet that carries a topic name together with an alias establishes the mapping for the
     * rest of the connection; a packet with an empty topic name refers back to it. An alias the
     * client never established, or one above the maximum we announced, is a protocol error.
     *
     * @param client The publishing client
     * @param packet The received PUBLISH; its `topic` is filled in from the alias when needed
     * @returns Whether the packet may be processed
     */
    private resolveTopicAlias(client: MqttClientConnection, packet: IncomingPublish): boolean {
        const alias = packet.properties?.topicAlias;
        if (alias === undefined) {
            return true;
        }

        if (!alias || alias > TOPIC_ALIAS_MAXIMUM) {
            this.adapter.log.warn(
                `Client [${client.id}] used the invalid topic alias ${alias} (maximum is ${TOPIC_ALIAS_MAXIMUM})`,
            );
            client.disconnect({ reasonCode: 0x94 }); // topic alias invalid
            client.close();
            return false;
        }

        client._topicAliases ||= new Map<number, MqttTopic>();

        if (packet.topic) {
            client._topicAliases.set(alias, packet.topic);
            return true;
        }

        const topic = client._topicAliases.get(alias);
        if (!topic) {
            this.adapter.log.warn(`Client [${client.id}] used the unknown topic alias ${alias}`);
            client.disconnect({ reasonCode: 0x94 }); // topic alias invalid
            client.close();
            return false;
        }

        packet.topic = topic;
        if (this.config.debug) {
            this.adapter.log.debug(`Client [${client.id}] topic alias ${alias} resolved to "${topic}"`);
        }
        return true;
    }

    private getMqttMessage<
        T extends {
            id: string;
            _subsID?: Record<string, MqttSubscription>;
            _subs?: Record<string, MqttSubscription>;
        },
    >(
        client: T,
        id: string,
        state: ioBroker.State | undefined | null,
        qos: 0 | 1 | 2 | undefined,
        retain: boolean | undefined,
        cb: (err: string | null, message?: MqttMessage, client?: T) => void,
        delivery: MessageDelivery = 'live',
    ): void {
        if (!this.id2topic[id]) {
            void this.adapter.getForeignObject(id, (err, obj) => {
                if (err) {
                    cb(`Client [${client.id}] Cannot resolve topic name for ID: ${id} (err: ${err})`);
                    return;
                }
                if (!obj) {
                    cb(`Client [${client.id}] Cannot resolve topic name for ID: ${id} (object not found)`);
                    return;
                }
                if (!obj._id) {
                    cb(
                        `Client [${client.id}] Cannot resolve topic name for ID: ${id} (object has no id): ${JSON.stringify(obj)}`,
                    );
                    return;
                }
                if (!obj.native?.topic) {
                    this.id2topic[obj._id] = convertID2topic(
                        obj._id,
                        null,
                        this.config.prefix,
                        this.adapter.namespace,
                        this.config.removePrefix,
                    );
                } else {
                    this.id2topic[obj._id] = obj.native.topic;
                }

                const topic = this.id2topic[obj._id];
                obj.common ||= {} as ioBroker.StateCommon;

                this.topic2id[topic] ||= { obj: obj as ioBroker.StateObject, id: obj._id };

                void this.getMqttMessage<T>(client, obj._id, state, qos, retain, cb, delivery);
            });
            return;
        }

        // Binary states are delivered as raw files via sendBinaryState2Client, never as a
        // (URL) string message. Skip here so the file URL is not published as the payload.
        if (this.topic2id[this.id2topic[id]]?.obj?.native?.binary) {
            cb(null, undefined, client);
            return;
        }

        // An expired value must not be handed out any more as the value the broker "already had".
        // Only the delivery is suppressed — the ioBroker state itself stays untouched, other
        // adapters keep using it.
        if (delivery === 'retained' && this.isExpired(id)) {
            this.adapter.log.debug(`Value of "${id}" expired, not sending it on subscribe`);
            cb(null, undefined, client);
            return;
        }

        // client has subscription for this ID
        let message: MqttMessage | undefined;
        let topic;
        let pattern;

        if (client._subsID?.[id]) {
            topic = this.id2topic[id];

            let payload: null | string;
            if (!state) {
                payload = null;
            } else {
                payload = state2string(state.val);
            }

            message = {
                topic: this.config.extraSet && state && !state.ack ? `${topic}/set` : topic,
                payload,
                qos: client._subsID[id].qos,
                retain: false,
                ts: Date.now(),
                count: 0,
                messageId: 0,
            };
        } else {
            //  Check patterns
            if (client._subs && (pattern = this.checkPattern(client._subs, id)) !== null) {
                topic = this.id2topic[id];
                // Cache the value
                client._subsID ||= {};
                client._subsID[id] = pattern;

                let payload;
                if (!state) {
                    payload = null;
                } else {
                    payload = state2string(state.val);
                }

                message = {
                    topic: this.config.extraSet && state && !state.ack ? `${topic}/set` : topic,
                    payload,
                    qos: pattern.qos,
                    retain: false,
                    ts: Date.now(),
                    count: 0,
                    messageId: 0,
                };
            }
        }

        if (message) {
            message = this.addMessageAttributes(message, {
                qos: qos ?? this.config.defaultQoS,
                retain: this.effectiveRetain(client, id, retain ?? false, delivery),
            });
            const properties = this.outgoingProperties(client, id);
            if (properties) {
                message.properties = properties;
            }
            if (this.messageExpiry[id]) {
                message.expiresAt = this.messageExpiry[id];
            }
        }

        cb(null, message, client);
    }

    private getNextMessageId(): number {
        const id = this.messageId;

        this.messageId++;
        if (this.messageId > 65535) {
            this.messageId = 1;
        }

        return id;
    }

    private addMessageAttributes(
        message: MqttMessage,
        attributes: {
            qos: 0 | 1 | 2;
            retain: boolean;
            binary?: boolean;
        },
    ): MqttMessage {
        return {
            ...message,
            qos: message.qos ?? attributes.qos,
            retain: attributes.retain,
            messageId: this.messageId,
            ts: Date.now(),
            count: 0,
            binary: attributes.binary,
            cmd: 'publish',
        };
    }

    private sendMessage2Client(
        client: MqttClientConnection,
        topic: MqttTopic,
        payload: ioBroker.State | ioBroker.StateValue,
        retain: boolean,
        binary?: boolean,
    ): void {
        const message = this.addMessageAttributes(
            {
                topic,
                payload: state2string(payload),
                binary,
                retain,
                ts: Date.now(),
                count: 0,
                qos: client._subsID?.[topic]?.qos ?? 0,
                messageId: 0,
            },
            { qos: client._subsID?.[topic]?.qos ?? 0, retain },
        );

        if (this.config.debug) {
            this.adapter.log.debug(
                `Client [${client.id}] send to this client "${message.topic}" (retain: ${message.retain}): ${message.payload !== 'null' ? message.payload : 'deleted'}`,
            );
        }

        this.deliver(client, message);
    }

    private sendState2Client(
        client: MqttClientConnection,
        id: string,
        state: ioBroker.State | null | undefined,
        qos?: 0 | 1 | 2,
        retain?: boolean,
        cb?: (id: string) => void,
        delivery: MessageDelivery = 'live',
    ): void {
        if (messageboxRegex.test(id)) {
            return;
        }

        // Binary state: send the raw file bytes instead of the stored URL string
        const binaryTopic = this.id2topic[id];
        if (binaryTopic && this.topic2id[binaryTopic]?.obj?.native?.binary) {
            this.sendBinaryState2Client(client, id, qos, retain, cb, delivery);
            return;
        }

        this.getMqttMessage<MqttClientConnection>(
            client,
            id,
            state,
            qos,
            retain,
            (_err, message, client) => {
                if (message) {
                    if (this.config.debug) {
                        this.adapter.log.debug(
                            `Client [${client!.id}] send to this client "${message.topic}": ${message.payload !== null ? message.payload : 'deleted'}`,
                        );
                    }

                    this.deliver(client!, message);
                }

                cb?.(id);
            },
            delivery,
        );
    }

    /**
     * Sends a binary state to a subscribed client by reading its raw bytes back from the file
     * storage (the state value itself only holds the file URL).
     */
    private sendBinaryState2Client(
        client: MqttClientConnection,
        id: string,
        qos?: 0 | 1 | 2,
        retain?: boolean,
        cb?: (id: string) => void,
        delivery: MessageDelivery = 'live',
    ): void {
        const topic = this.id2topic[id];
        const file: string | undefined = topic ? this.topic2id[topic]?.obj?.native?.file : undefined;

        // Determine whether the client is subscribed and with which QoS
        let subQos: 0 | 1 | 2 | undefined;
        if (client._subsID?.[id]) {
            subQos = client._subsID[id].qos;
        } else if (client._subs) {
            const pattern = this.checkPattern(client._subs, id);
            if (pattern) {
                subQos = pattern.qos;
                client._subsID ||= {};
                client._subsID[id] = pattern;
            }
        }

        if (!topic || !file || subQos === undefined) {
            // not subscribed or file unknown
            cb?.(id);
            return;
        }

        const subscribedQos: 0 | 1 | 2 = subQos;

        this.adapter
            .readFileAsync(this.adapter.namespace, file)
            .then(res => {
                const data = res?.file;
                if (data === undefined || data === null) {
                    cb?.(id);
                    return;
                }
                const wireRetain = this.effectiveRetain(client, id, retain ?? false, delivery);
                const message = this.addMessageAttributes(
                    {
                        topic,
                        payload: data as unknown as string,
                        qos: subscribedQos,
                        retain: wireRetain,
                        ts: Date.now(),
                        count: 0,
                        messageId: 0,
                    },
                    { qos: qos ?? subscribedQos ?? this.config.defaultQoS, retain: wireRetain, binary: true },
                );

                if (this.config.debug) {
                    this.adapter.log.debug(
                        `Client [${client.id}] send binary to this client "${message.topic}" (${(data as Buffer).length} bytes)`,
                    );
                }

                this.deliver(client, message);
                cb?.(id);
            })
            .catch(err => {
                this.adapter.log.warn(`Cannot read binary file "${file}" for topic "${topic}": ${err as Error}`);
                cb?.(id);
            });
    }

    private sendStates2Client(client: MqttClientConnection, list: string[]): void {
        if (list?.length) {
            const id = list.shift() || '';
            this.sendState2Client(
                client,
                id,
                this.states[id],
                0,
                !this.config.noRetain,
                () => setTimeout(() => this.sendStates2Client(client, list), this.config.sendInterval),
                // these are the values the broker already had, not live forwards
                'retained',
            );
        } else {
            //return;
        }
    }

    private resendMessages2Client(client: MqttClientConnection, messages: MqttMessage[], i?: number): void {
        i ||= 0;
        if (messages && i < messages.length) {
            if (messages[i].expiresAt && messages[i].expiresAt! <= Date.now()) {
                this.adapter.log.debug(
                    `Client [${client.id}] Queued message for "${messages[i].topic}" expired, not resending it`,
                );
                messages.splice(i, 1);
                setImmediate(() => this.resendMessages2Client(client, messages, i));
                return;
            }
            try {
                messages[i].ts = Date.now();
                messages[i].count = 0; // keep at 0 in case checkResends fires between resend steps
                this.adapter.log.debug(
                    `Client [${client.id}] Resend messages on connect: ${messages[i].topic} and id ${messages[i].messageId} (${messages[i].cmd}) = ${messages[i].payload}`,
                );
                if (messages[i].cmd === 'publish') {
                    messages[i].messageId = this.getNextMessageId();
                    client.publish(messages[i]);
                }
            } catch (e) {
                this.adapter.log.warn(`Client [${client.id}] Cannot resend message: ${e as Error}`);
            }

            if (this.config.sendInterval) {
                setTimeout(() => this.resendMessages2Client(client, messages, i + 1), this.config.sendInterval);
            } else {
                setImmediate(() => this.resendMessages2Client(client, messages, i + 1));
            }
        } else {
            // return;
        }
    }

    /*
     4.7.1.2 Multi-level wildcard

     The number sign (‘#’ U+0023) is a wildcard character that matches any number of levels within a topic. The multi-level wildcard represents the parent and any number of child levels. The multi-level wildcard character MUST be specified either on its own or following a topic level separator. In either case it MUST be the last character specified in the Topic Filter [MQTT-4.7.1-2].

     Non-normative comment,
     For example, if a Client subscribes to “sport/tennis/player1/#”, it would receive messages published using these topic names:
     ·         “sport/tennis/player1”
     ·         “sport/tennis/player1/ranking”
     ·         “sport/tennis/player1/score/wimbledon”

     Non-normative comment
     ·         “sport/#” also matches the singular “sport”, since # includes the parent level.
     ·         “#” is valid and will receive every Application Message
     ·         “sport/tennis/#” is valid
     ·         “sport/tennis#” is not valid
     ·         “sport/tennis/#/ranking” is not valid

     */
    private checkPattern(
        patterns: {
            [topic: string]: {
                regex: RegExp;
                qos: 0 | 1 | 2;
                pattern: MqttPattern;
            };
        },
        id: string,
    ): {
        regex: RegExp;
        qos: 0 | 1 | 2;
        pattern: MqttPattern;
    } | null {
        const pattern = Object.keys(patterns).find(p => patterns[p].regex.test(id));

        return pattern ? patterns[pattern] : null;
    }

    private async processTopic(
        id: string,
        topic: MqttTopic,
        message: ioBroker.State | ioBroker.StateValue | null | undefined,
        qos: 0 | 1 | 2,
        retain: boolean,
        isAck: boolean,
        ignoreClient: MqttClientConnection,
        expiryInterval?: number,
    ): Promise<void> {
        if (id === `${this.adapter.namespace}.info.connection`) {
            this.adapter.log.debug(`Ignore State update for ${id} because adapter internal state.`);
            return;
        }

        if (ignoreClient.__secret) {
            this.lastPublisher[id] = { secret: ignoreClient.__secret, ts: Date.now() };
        }

        if (expiryInterval) {
            this.messageExpiry[id] = Date.now() + expiryInterval * 1000;
        } else {
            delete this.messageExpiry[id];
        }

        // expand an old version of objects
        // The payload is parsed only for type detection (the value handling further down
        // still uses the raw `message`): an ioBroker state object yields the type of its
        // `val` (a `val` of null is indeterminate → 'mixed'), and a JSON string that is not
        // a valid ioBroker state object yields 'mixed'.
        const parsedForType = convertMessage(topic, message, this.adapter, this.config.parseCharCodes);
        let messageType = typeof parsedForType.message;
        let stateType: ioBroker.CommonType = Array.isArray(parsedForType.message)
            ? 'array'
            : messageType === 'string' ||
                messageType === 'number' ||
                messageType === 'boolean' ||
                messageType === 'object'
              ? messageType
              : 'mixed';

        // if it is an ioBroker State object, derive the type from its `val`
        if (parsedForType.isStateObject) {
            if (parsedForType.message.val === null) {
                // val is null: type cannot be determined, use 'mixed'
                stateType = 'mixed';
            } else {
                messageType = typeof parsedForType.message.val;
                stateType = Array.isArray(parsedForType.message.val)
                    ? 'array'
                    : messageType === 'string' ||
                        messageType === 'number' ||
                        messageType === 'boolean' ||
                        messageType === 'object'
                      ? messageType
                      : 'mixed';
            }
        } else if (typeof parsedForType.message === 'string' && parsedForType.message[0] === '{') {
            // JSON payload that is not a valid ioBroker state object (non-state properties)
            stateType = 'mixed';
        }

        // update a type of state if necessary
        const obj = this.topic2id[topic].obj;
        if (
            obj &&
            this.namespaceRegEx.test(id) &&
            (!obj.native?.topic || (obj.common && obj.common.type !== 'mixed' && obj.common.type !== stateType))
        ) {
            if (obj.common && obj.common.type !== 'mixed' && obj.common.type !== stateType) {
                // mqtt topics could change types, but log it to communicate to the user if a type is frequently fluctuating
                this.adapter.log.info(`Server: Changed type of "${id}" from "${obj.common.type}" to "${stateType}"`);
                obj.common.type = stateType;
            }

            obj.native ||= {};
            obj.native.topic = topic;
            try {
                await this.adapter.setForeignObject(id, obj);
            } catch (e) {
                this.adapter.log.error(`Could not update object "${id}": ${(e as Error).message}`);
            }
        }

        if (this.config.debug) {
            this.adapter.log.debug(`Server received "${topic}" (${typeof message}): ${JSON.stringify(message)}`);
        }

        if (parsedForType.message != null) {
            let value: ioBroker.State;
            if (typeof parsedForType.message === 'object') {
                if (parsedForType.isStateObject) {
                    value = parsedForType.message;
                } else {
                    value = { val: JSON.stringify(parsedForType.message), ack: isAck } as ioBroker.State;
                }
            } else {
                value = { val: parsedForType.message, ack: isAck } as ioBroker.State;
            }
            if (
                value.val !== undefined &&
                value.val !== null &&
                this.namespaceRegEx.test(this.topic2id[topic].id) &&
                this.topic2id[topic].obj?.common &&
                this.topic2id[topic].obj.common.type !== 'mixed' &&
                this.topic2id[topic].obj.common.type !== typeof value.val
            ) {
                this.adapter.log.info(
                    `Server: Changed type of "${this.topic2id[topic].id}" from "${this.topic2id[topic].obj.common.type}" to "mixed"`,
                );
                try {
                    await this.adapter.extendObject(this.topic2id[topic].id, { common: { type: 'mixed' } });
                } catch (err) {
                    this.adapter.log.warn(
                        `Error while updating object "${this.topic2id[topic].id}" for Server: ${err as Error}`,
                    );
                }
                this.topic2id[topic].obj.common.type = 'mixed';
            }
            try {
                await this.adapter.setForeignStateAsync(id, value);
            } catch {
                // ignore
            }

            this.states[id] = value;
        } else {
            this.states[id] = { val: null, ack: isAck } as ioBroker.State;
        }

        // send a message to all other clients
        if (this.config.onchange && this.server && parsedForType.message != null) {
            setImmediate(() => {
                let state: ioBroker.State;
                if (typeof parsedForType.message === 'object') {
                    if (parsedForType.isStateObject) {
                        state = parsedForType.message;
                    } else {
                        state = { val: JSON.stringify(parsedForType.message) } as ioBroker.State;
                    }
                } else {
                    state = { val: parsedForType.message, ack: isAck } as ioBroker.State;
                }

                const sharedRecipients = this.resolveSharedRecipients(id);

                Object.keys(this.clients).forEach(k => {
                    // if 'get' and 'set' have different topic names, send state to issuing a client too.
                    if (
                        this.mayReceiveOwnMessage(this.clients[k], ignoreClient, id) &&
                        this.isRecipient(this.clients[k], id, sharedRecipients)
                    ) {
                        this.sendState2Client(this.clients[k], id, state, qos, retain);
                    }
                });
            });
        }
        // ELSE
        // this will be done indirectly. The message will be sent to js-controller, and if the adapter is subscribed, it gets this message over stateChange
    }

    /**
     * Resolves a received topic back to the state ID it was published from, for IDs that cannot be
     * restored from the topic because "+"/"#"/whitespace were replaced with "_".
     *
     * This must also correct an *already cached* mapping: `topic2id` is filled first-wins by
     * `sendState2Client`, so on an installation that still carries a leftover
     * `mqtt.<n>.<lossy topic>` state (created by this bug before it was fixed) that leftover can
     * claim the topic before any message arrives. The cache entry is dropped so the caller
     * re-runs the object lookup for the correct ID.
     *
     * The scan itself is O(number of published states), so it runs at most once per topic.
     *
     * @param topic The received topic (already stripped of a possible "/set" suffix)
     * @param id The ID the topic was converted to (or the cached one)
     * @returns The original state ID, or `id` unchanged if the topic does not belong to one
     */
    private resolveTopicId(topic: MqttTopic, id: string): string {
        if (this.resolvedTopics[topic]) {
            return id;
        }
        this.resolvedTopics[topic] = true;

        const knownId = findIdForTopic(
            topic,
            this.states,
            this.config.prefix,
            this.adapter.namespace,
            this.config.removePrefix,
        );

        if (!knownId || knownId === id) {
            return id;
        }

        this.adapter.log.debug(`Topic "${topic}" resolved to the published state "${knownId}"`);

        if (this.topic2id[topic]) {
            this.adapter.log.warn(
                `Topic "${topic}" was mapped to "${this.topic2id[topic].id}" instead of "${knownId}". ` +
                    `"${this.topic2id[topic].id}" is a leftover of an earlier version and can be deleted.`,
            );
            delete this.topic2id[topic];
        }

        return knownId;
    }

    private async checkObject(id: string, topic: MqttTopic, message?: string | null): Promise<void> {
        // Topic of a state we publish ourselves whose ID cannot be restored from it
        // ("+"/"#"/whitespace became "_") — resolve it back to the original state.
        // For a received message this already happened in `onMessage`; this call covers the
        // subscribe and "last will" paths.
        id = this.resolveTopicId(topic, id);

        if (isIgnoredTopic(id, this.ignoredTopicsRegexes)) {
            return;
        }
        this.topic2id[topic] ||= {
            id: '',
            obj: { _id: '', common: {} as ioBroker.StateCommon, native: {}, type: 'state' },
            processing: true,
        };

        if (this.config.debug) {
            this.adapter.log.debug(`Check object for topic "${topic}"`);
        }

        let obj: ioBroker.Object | undefined | null = null;
        try {
            obj = await this.adapter.getObjectAsync(id);
        } catch {
            // ignore
        }

        if (
            obj &&
            obj._id?.startsWith(`${this.adapter.namespace}.`) &&
            obj.type === 'folder' &&
            obj.native?.autocreated === 'by automatic ensure logic'
        ) {
            // ignore a default created object because we now have a more defined one
            obj = null;
        }

        if (!obj) {
            try {
                obj = await this.adapter.getForeignObjectAsync(id);
            } catch {
                // ignore
            }
            if (
                obj &&
                obj._id?.startsWith(`${this.adapter.namespace}.`) &&
                obj.type === 'folder' &&
                obj.native?.autocreated === 'by automatic ensure logic'
            ) {
                // ignore a default created object because we now have a more defined one
                obj = null;
            }

            if (!obj) {
                id = `${this.adapter.namespace}.${id}`;

                if (this.config.ignoreNewObjects) {
                    this.adapter.log.warn(`Object ${id} ignored and not created`);
                    throw new Error(`Object ${id} not exists`);
                }

                // only for type detection
                const parsedMessage = convertMessage(topic, message, this.adapter, this.config.parseCharCodes);
                let stateType: ioBroker.CommonType;
                if (parsedMessage.isStateObject) {
                    stateType = typeof parsedMessage.message.val as ioBroker.CommonType;
                    stateType = Array.isArray(parsedMessage.message.val)
                        ? 'array'
                        : parsedMessage.message.val !== null &&
                            (stateType === 'string' ||
                                stateType === 'number' ||
                                stateType === 'boolean' ||
                                stateType === 'object')
                          ? stateType
                          : 'mixed';
                } else {
                    const messageType = typeof parsedMessage.message;
                    stateType = Array.isArray(parsedMessage.message)
                        ? 'array'
                        : parsedMessage.message !== null &&
                            (messageType === 'string' ||
                                messageType === 'number' ||
                                messageType === 'boolean' ||
                                messageType === 'object')
                          ? messageType
                          : 'mixed';
                }

                // create state
                obj = {
                    _id: id,
                    common: {
                        name: topic,
                        write: true,
                        read: true,
                        role: 'variable',
                        desc: 'mqtt server variable',
                        type: stateType,
                    },
                    native: {
                        topic,
                    },
                    type: 'state',
                };
                if (typeof parsedMessage.message === 'string' && parsedMessage.message[0] === '{') {
                    // JSON payload that is not a valid ioBroker state object (non-state properties)
                    obj.common.type = 'mixed';
                }

                this.adapter.log.debug(`Create object for topic: ${topic}[ID: ${id}]`);
                try {
                    await this.adapter.setForeignObject(id, obj);
                } catch {
                    // ignore
                }
            } else if (this.config.debug) {
                this.adapter.log.debug(`    Found object for topic "${topic}" = ${obj._id}`);
            }
        } else if (this.config.debug) {
            this.adapter.log.debug(`    Found object for topic "${topic}" = ${obj._id}`);
        }

        if (obj && !obj._id) {
            obj._id = id;
        }

        const stateObj: ioBroker.StateObject = obj as ioBroker.StateObject;

        this.topic2id[topic].id = stateObj._id;
        this.topic2id[topic].obj = stateObj;
        this.topic2id[topic].processing = false;

        // do not wait for the finish of the function
        ensureObjectStructure(this.adapter, stateObj._id, this.verifiedObjects).catch(e => this.adapter.log.error(e));
    }

    /**
     * Stores a received binary payload as a file in the adapter's file storage, updates the
     * corresponding state with the file URL and forwards the raw bytes to the other subscribed
     * clients. Used for topics matching `binaryTopics`.
     */
    private async storeBinaryMessage(
        id: string,
        topic: MqttTopic,
        message: Buffer,
        isAck: boolean,
        qos: 0 | 1 | 2,
        retain: boolean,
        ignoreClient: MqttClientConnection,
    ): Promise<void> {
        const file = topic2filename(topic);

        // Resolve / create the object only once, then reuse it from the cache
        if (!this.topic2id[topic]?.obj?.native?.binary) {
            let obj: ioBroker.Object | undefined | null = null;
            try {
                obj = await this.adapter.getObjectAsync(id);
            } catch {
                // ignore
            }
            if (!obj) {
                try {
                    obj = await this.adapter.getForeignObjectAsync(id);
                } catch {
                    // ignore
                }
            }
            if (
                obj?._id?.startsWith(`${this.adapter.namespace}.`) &&
                obj.type === 'folder' &&
                obj.native?.autocreated === 'by automatic ensure logic'
            ) {
                // ignore a default created folder object because we now have a more defined one
                obj = null;
            }

            const fullId = obj?._id || `${this.adapter.namespace}.${id}`;

            if (!obj) {
                if (this.config.ignoreNewObjects) {
                    this.adapter.log.warn(`Object ${fullId} ignored and not created`);
                    return;
                }
                obj = {
                    _id: fullId,
                    type: 'state',
                    common: {
                        name: topic,
                        read: true,
                        write: false,
                        role: 'url',
                        type: 'string',
                        desc: 'mqtt binary payload (stored as file)',
                    },
                    native: { topic, binary: true, file, meta: this.adapter.namespace },
                };
                this.adapter.log.debug(`Create binary (file) object for topic: ${topic}[ID: ${fullId}]`);
                try {
                    await this.adapter.setForeignObject(fullId, obj);
                } catch (err) {
                    this.adapter.log.error(`Could not create object "${fullId}": ${(err as Error).message}`);
                    return;
                }
            } else if (
                !obj.native?.binary ||
                obj.native.file !== file ||
                obj.native.topic !== topic ||
                obj.common?.role !== 'url'
            ) {
                // migrate an existing object to the file-based representation
                obj.native ||= {};
                obj.native.binary = true;
                obj.native.file = file;
                obj.native.topic = topic;
                obj.native.meta = this.adapter.namespace;
                obj.common ||= {} as ioBroker.StateCommon;
                obj.common.role = 'url';
                obj.common.type = 'string';
                try {
                    await this.adapter.setForeignObject(fullId, obj);
                } catch (err) {
                    this.adapter.log.error(`Could not update object "${fullId}": ${(err as Error).message}`);
                }
            }

            this.topic2id[topic] = { id: fullId, obj: obj as ioBroker.StateObject };
            this.id2topic[fullId] = topic;

            ensureObjectStructure(this.adapter, fullId, this.verifiedObjects).catch(e => this.adapter.log.error(e));
        }

        const entry = this.topic2id[topic];

        try {
            await this.adapter.writeFileAsync(this.adapter.namespace, file, message);
        } catch (err) {
            this.adapter.log.error(`Cannot store binary payload of "${topic}" as file "${file}": ${err as Error}`);
            return;
        }

        const url = `/files/${this.adapter.namespace}/${file}`;
        const state = { val: url, ack: isAck } as ioBroker.State;
        if (this.config.debug) {
            this.adapter.log.debug(`Server stored binary "${topic}" (${message.length} bytes) as ${url}`);
        }
        try {
            await this.adapter.setForeignStateAsync(entry.id, state);
        } catch {
            // ignore
        }
        this.states[entry.id] = state;

        // forward the binary to all other subscribed clients (like the onchange path in processTopic)
        if (this.config.onchange && this.server) {
            setImmediate(() => {
                const sharedRecipients = this.resolveSharedRecipients(entry.id);

                Object.keys(this.clients).forEach(k => {
                    if (
                        this.mayReceiveOwnMessage(this.clients[k], ignoreClient, entry.id) &&
                        this.isRecipient(this.clients[k], entry.id, sharedRecipients)
                    ) {
                        this.sendState2Client(this.clients[k], entry.id, state, qos, retain);
                    }
                });
            });
        }
    }

    private async receivedTopic(packet: MqttMessage, client: MqttClientConnection): Promise<void> {
        let isAck = true;
        let topic = packet.topic;
        const message = packet.payload;
        const qos = packet.qos;
        const retain = packet.retain;
        const now = Date.now();
        let id;

        if (this.config.extraSet && packet.topic.match(/\/set$/)) {
            isAck = false;
            packet.topic = packet.topic.substring(0, packet.topic.length - 4);
            topic = packet.topic;
        }

        if (this.topic2id[topic]) {
            id =
                this.topic2id[topic].id ||
                convertTopic2id(topic, false, this.config.prefix, this.adapter.namespace, this.config.dotToUnderscore);
        } else {
            id = convertTopic2id(topic, false, this.config.prefix, this.adapter.namespace, this.config.dotToUnderscore);
        }

        if (!id) {
            this.adapter.log.error(`Client [${client.id}] Invalid topic name: ${JSON.stringify(topic)}`);
            return;
        }
        if (isIgnoredTopic(id, this.ignoredTopicsRegexes)) {
            return;
        }

        // Binary payload: store the raw bytes as a file instead of a (lossy) string state
        if (isBinaryTopic(id, this.binaryTopicsRegexes)) {
            await this.storeBinaryMessage(id, topic, message as unknown as Buffer, isAck, qos, retain, client);
            return;
        }

        // If state is unknown => create mqtt.X.topic
        if (`${this.adapter.namespace}.${id}`.length > this.config.maxTopicLength) {
            this.adapter.log.warn(`Client [${client.id}] Topic name is too long: ${id.substring(0, 100)}...`);
            return;
        }

        // Topic of a state we publish ourselves whose ID cannot be restored from it
        // ("+"/"#"/whitespace became "_") — resolve it back to the original state. `checkObject`
        // does the same, but it is only reached on a cache miss and the cache may already point
        // to a leftover state (see `resolveTopicId`).
        id = this.resolveTopicId(topic, id);

        if (!this.topic2id[topic]) {
            try {
                await this.checkObject(id, topic, message);
            } catch {
                return;
            }
        } else if (this.topic2id[topic].processing) {
            // still looking for ID
            this.topic2id[topic].message = convertMessage(topic, message, this.adapter, this.config.parseCharCodes);
            if (this.config.debug) {
                this.adapter.log.debug(
                    `Client [${client.id}] Server received (but in process) "${topic}" (${typeof this.topic2id[topic].message?.message}): ${JSON.stringify(this.topic2id[topic].message)}`,
                );
            }
            return;
        }

        let parsedMessage:
            | { message: string | number | boolean | Record<string, any>; isStateObject: false }
            | { message: ioBroker.State; isStateObject: true };

        if (this.topic2id[topic].message) {
            // get last received message
            parsedMessage = this.topic2id[topic].message!;
            delete this.topic2id[topic].message;
        } else if (this.topic2id[topic].obj) {
            parsedMessage = convertMessage(topic, message, this.adapter, this.config.parseCharCodes, client.id);
        }

        if (qos) {
            Object.keys(this.persistentSessions).forEach(clientId => {
                if (clientId !== client.id && !this.persistentSessions[clientId].connected) {
                    const state = parsedMessage.isStateObject
                        ? parsedMessage.message
                        : ({
                              val:
                                  typeof parsedMessage.message === 'object'
                                      ? JSON.stringify(parsedMessage.message)
                                      : parsedMessage.message,
                              ack: isAck,
                          } as ioBroker.State);

                    // try to collect this message if a client subscribed
                    this.getMqttMessage<PersistentSession>(
                        this.persistentSessions[clientId],
                        id,
                        state,
                        this.config.defaultQoS,
                        true,
                        (_err, sendMessage, persistentClient) =>
                            // if sendMessage is defined, then the message should be delivered because subscribed, but we deliver the original message
                            sendMessage &&
                            persistentClient &&
                            this.addMessageWithTopicCheck(persistentClient._messages, {
                                topic,
                                qos,
                                retain,
                                messageId: packet.messageId || sendMessage.messageId,
                                ts: now,
                                payload: message,
                                count: 0,
                                cmd: 'publish',
                            }),
                    );
                }
            });
        }

        await this.processTopic(
            this.topic2id[topic].id,
            topic,
            message,
            qos,
            retain,
            isAck,
            client,
            packet.properties?.messageExpiryInterval,
        );
    }

    private addMessageWithTopicCheck(arr: MqttMessage[], message: MqttMessage): void {
        for (let i = 0; i < arr.length; i++) {
            if (arr[i].topic === message.topic) {
                // if same topic we do not add a new entry but pot. update existing of newer
                if (message.ts! > arr[i].ts!) {
                    arr[i] = message;
                }
                return;
            }
        }
        arr.push(message);
    }

    /**
     * Publishes the last will of a client whose connection dropped.
     *
     * MQTT 5 lets a client ask for a delay, so a short network hiccup does not announce it as
     * offline: the will is only published once the delay passed and the client did not come back
     * (MQTT-5.0 3.1.3.2.2). The delay is capped by the session expiry interval, because the will
     * must not outlive the session. MQTT 3.1.1 has no delay and is published right away.
     *
     * @param client The client that just disconnected
     */
    private publishWill(client: MqttClientConnection): void {
        const will = { ...client._will, messageId: 0 };
        const send = (): void => {
            delete this.delayedWills[client.id];
            void this.receivedTopic(will, client).catch(() => null);
        };

        let delay = client._willDelayInterval ?? 0;
        if (client._sessionExpiryInterval !== undefined) {
            delay = Math.min(delay, client._sessionExpiryInterval);
        }

        if (!delay) {
            send();
            return;
        }

        this.adapter.log.debug(`Client [${client.id}] will is delayed by ${delay} seconds`);
        if (this.delayedWills[client.id]) {
            this.adapter.clearTimeout(this.delayedWills[client.id]);
        }
        this.delayedWills[client.id] = this.adapter.setTimeout(send, delay * 1000);
    }

    /**
     * The salted password for SCRAM, derived from the configured one exactly once.
     *
     * @returns The salted password
     */
    private getScramSaltedPassword(): Promise<Buffer> {
        this.scramSaltedPassword ||= saltPassword(this.config.pass || '', this.scramSalt);
        return this.scramSaltedPassword;
    }

    /**
     * Starts a SCRAM-SHA-256 exchange: takes the client's first message and answers with an AUTH
     * packet carrying the server's first message (MQTT-5.0 4.12).
     *
     * @param client The connecting client
     * @param clientFirst The authentication data of its CONNECT packet
     */
    private startScram(client: MqttClientConnection, clientFirst?: Buffer): void {
        if (!clientFirst?.length) {
            this.adapter.log.warn(`Client [${client.id}] started SCRAM without a first message`);
            this.rejectAuthentication(client);
            return;
        }

        const exchange = new ScramExchange(this.config.user, this.scramSalt);
        let serverFirst: Buffer;
        try {
            serverFirst = exchange.begin(clientFirst);
        } catch (e) {
            this.adapter.log.warn(`Client [${client.id}] sent an unusable SCRAM message: ${(e as ScramError).message}`);
            this.rejectAuthentication(client);
            return;
        }

        client._scram = exchange;
        client.auth({
            reasonCode: 0x18, // continue authentication
            properties: { authenticationMethod: SCRAM_SHA_256, authenticationData: serverFirst },
        });
    }

    /**
     * Finishes a SCRAM exchange with the client's proof.
     *
     * @param client The authenticating client
     * @param clientFinal The authentication data of its AUTH packet
     * @param reAuthentication Whether this is a re-authentication of an already connected client
     */
    private async finishScram(
        client: MqttClientConnection,
        clientFinal: Buffer | undefined,
        reAuthentication: boolean,
    ): Promise<void> {
        const exchange = client._scram;
        if (!exchange || !clientFinal?.length) {
            this.rejectAuthentication(client, reAuthentication);
            return;
        }

        let serverFinal: Buffer;
        try {
            serverFinal = exchange.finish(clientFinal, await this.getScramSaltedPassword());
        } catch (e) {
            // Always the same message: which half was wrong is not the client's business.
            this.adapter.log.warn(
                `Client [${client.id}] failed the SCRAM authentication (${(e as ScramError).message})`,
            );
            this.rejectAuthentication(client, reAuthentication);
            return;
        } finally {
            client._scram = undefined;
        }

        client.authenticated = true;
        this.adapter.log.info(`Client [${client.id}] authenticated with ${SCRAM_SHA_256}`);

        if (reAuthentication) {
            // the connection stays as it is, only the proof was renewed
            client.auth({
                reasonCode: 0x00, // success
                properties: { authenticationMethod: SCRAM_SHA_256, authenticationData: serverFinal },
            });
            return;
        }

        const complete = client._completeConnect;
        client._completeConnect = undefined;
        client._scramServerFinal = serverFinal;
        complete?.();
    }

    /**
     * Rejects an authentication attempt and closes the connection.
     *
     * @param client The client to reject
     * @param reAuthentication Whether an established connection is being torn down
     */
    private rejectAuthentication(client: MqttClientConnection, reAuthentication = false): void {
        client.authenticated = false;
        client._scram = undefined;
        client._completeConnect = undefined;

        if (reAuthentication) {
            // an established connection is ended with a DISCONNECT, not with a CONNACK
            client.disconnect({ reasonCode: 0x87 }); // not authorized
        } else {
            client.connack({ reasonCode: 0x87 }); // not authorized
        }
        client.close();
    }

    private clientClose(client: MqttClientConnection, reason?: string): void {
        if (!client) {
            return;
        }

        if (this.persistentSessions[client.id]) {
            this.persistentSessions[client.id].connected = false;
        }

        // A shared subscription only makes sense while the client is there; on reconnect it
        // subscribes again. Leaving now keeps messages from being drawn for a gone member.
        this.leaveSharedGroups(client.id);

        // never keep a half finished authentication around
        client._scram = undefined;
        client._completeConnect = undefined;
        client._scramServerFinal = undefined;

        // Anything that was still waiting for a free slot belongs into the session queue, so a
        // persistent session replays it on the next connection instead of losing it.
        if (client._pendingMessages?.length) {
            client._messages ||= [];
            client._messages.push(...client._pendingMessages);
            client._pendingMessages = [];
        }

        if (client._sendOnStart) {
            clearTimeout(client._sendOnStart);
            client._sendOnStart = null;
        }
        if (client._resendonStart) {
            clearTimeout(client._resendonStart);
            client._resendonStart = null;
        }

        try {
            if (this.clients[client.id] && client.__secret === this.clients[client.id].__secret) {
                this.adapter.log.info(`Client [${client.id}] connection closed: ${reason}`);
                delete this.clients[client.id];
                this.updateClients();
                if (client._will && reason !== 'disconnected') {
                    this.publishWill(client);
                }
                client.destroy();
            } else {
                client.destroy();
            }
        } catch (e) {
            this.adapter.log.warn(`Client [${client.id}] Cannot close client: ${e as Error}`);
        }
    }

    private validateRequest(
        type: 'publish' | 'pubrec' | 'pubcomp' | 'pubrel' | 'subscribe' | 'unsubscribe' | 'pingreq' | 'puback',
        client: MqttClientConnection,
    ): boolean {
        if (this.config.user && !client.authenticated) {
            this.adapter.log.warn(`Client [${client.id}] sends ${type} after unsuccessful authentication. Ignore!`);
            return false;
        }

        if (this.clients[client.id] && client.__secret !== this.clients[client.id].__secret) {
            this.adapter.log.debug(
                `Old client ${client.id} with secret ${client.__secret} sends ${type}. Ignore! Actual secret is ${this.clients[client.id].__secret}`,
            );
            return false;
        }

        return true;
    }

    private startServer(
        socket: Server | WsServer,
        server: HttpHttpsServer | null,
        port: number,
        bind: string,
        ssl: boolean,
        ws: boolean,
    ): void {
        // Event variable to hold a connection event type
        let connectionEvent: 'secureConnection' | 'connection';

        // Check if SSL/TLS connection is required
        if (this.config.ssl) {
            // Set event variable to SSL/TLS connection
            connectionEvent = 'secureConnection';
        } else {
            // Set event variable to plain TCP connection
            connectionEvent = 'connection';
        }

        // Use event variable to start the connection
        socket.on(connectionEvent, (stream: any) => {
            const client = new MqttConnection(ws ? wsStream(stream) : stream) as MqttClientConnection;

            // Store unique connection identifier
            client.__secret = `${Date.now()}_${Math.round(Math.random() * 10000)}`;

            client.on(
                'connect',
                (options: {
                    clientId: string;
                    cleanSession?: boolean;
                    clean?: boolean;
                    keepalive: number;
                    username?: string;
                    password?: string;
                    will?: {
                        topic: string;
                        payload: string;
                        qos: 0 | 1 | 2;
                        retain: boolean;
                        properties?: { willDelayInterval?: number };
                    };
                    properties?: {
                        sessionExpiryInterval?: number;
                        receiveMaximum?: number;
                        authenticationMethod?: string;
                        authenticationData?: Buffer;
                    };
                }): void => {
                    // set client id
                    client.id = options.clientId;

                    // MQTT 5 replaced the "clean session" flag: "clean start" only says whether an
                    // existing session is resumed, while the session expiry interval decides whether
                    // it survives the connection at all (MQTT-5.0 3.1.2.11.2). An interval of 0 —
                    // and the absence of the property — means the session ends with the connection.
                    client._sessionExpiryInterval =
                        client.protocolVersion === 5 ? (options.properties?.sessionExpiryInterval ?? 0) : undefined;

                    // How many unacknowledged QoS 1/2 messages this client accepts at once. The
                    // default of 65535 means "no practical limit" (MQTT-5.0 3.1.2.11.3).
                    client._receiveMaximum =
                        client.protocolVersion === 5 ? (options.properties?.receiveMaximum ?? 65535) : undefined;
                    client._pendingMessages = [];

                    if (this.config.forceCleanSession === 'clean') {
                        client.cleanSession = true;
                    } else if (this.config.forceCleanSession === 'keep') {
                        client.cleanSession = false;
                    } else if (client._sessionExpiryInterval !== undefined) {
                        client.cleanSession = client._sessionExpiryInterval === 0;
                    } else {
                        // The old logic always resulted in 'undefined' when cleanSession was not active,
                        // because options.cleanSession was undefined. This led to client.cleanSession being set to undefined.
                        // client.cleanSession = options.cleanSession === undefined ? options.cleanSession : options.clean;

                        // The improved logic below should be better:
                        client.cleanSession = options.cleanSession !== undefined ? options.cleanSession : options.clean;
                    }

                    client._keepalive = options.keepalive;

                    // get possible an old client
                    const oldClient = this.clients[client.id];

                    // Everything that happens once the client is authenticated. Enhanced
                    // authentication needs another round trip first, so this cannot run inline.
                    const completeConnect = (): void => {
                        if (oldClient) {
                            this.adapter.log.info(
                                `Client [${client.id}] reconnected. Old secret ${this.clients[client.id].__secret}. New secret ${client.__secret}`,
                            );
                            // need to destroy the old client

                            if (client.__secret !== this.clients[client.id].__secret) {
                                // it is another socket!!
                                // It was the following situation:
                                // - old connection was active
                                // - new connection is on the same TCP
                                // Just forget him
                                // oldClient.destroy();
                            }
                        } else {
                            this.adapter.log.info(`Client [${client.id}] connected with secret ${client.__secret}`);
                        }

                        let sessionPresent = false;

                        if (!client.cleanSession && this.config.storeClientsTime !== 0) {
                            if (this.persistentSessions[client.id]) {
                                sessionPresent = true;
                                this.persistentSessions[client.id].lastSeen = Date.now();
                            } else {
                                this.persistentSessions[client.id] = {
                                    id: client.id,
                                    _subsID: {},
                                    _subs: {},
                                    _messages: [],
                                    lastSeen: Date.now(),
                                };
                            }
                            client._messages = this.persistentSessions[client.id]._messages || [];
                            this.persistentSessions[client.id].connected = true;
                        } else if (client.cleanSession && this.persistentSessions[client.id]) {
                            delete this.persistentSessions[client.id];
                        }
                        client._messages ||= [];

                        client.connack({
                            returnCode: 0,
                            sessionPresent,
                            // Only MQTT 5 has CONNACK properties; MqttConnection drops them otherwise.
                            // Only what differs from the defaults is announced — "maximum QoS" for
                            // example must not be sent at all when it is 2 (MQTT-5.0 3.2.2.3.4).
                            properties: {
                                topicAliasMaximum: TOPIC_ALIAS_MAXIMUM,
                                // The client verifies the server with this, so it knows it did not
                                // hand its proof to an impostor (MQTT-5.0 4.12).
                                ...(client._scramServerFinal
                                    ? {
                                          authenticationMethod: client._authMethod,
                                          authenticationData: client._scramServerFinal,
                                      }
                                    : {}),
                            },
                        });
                        client._scramServerFinal = undefined;
                        this.clients[client.id] = client;
                        this.updateClients();

                        // The client is back before its will was published, so it must not be sent
                        // any more (MQTT-5.0 3.1.3.2.2).
                        if (this.delayedWills[client.id]) {
                            this.adapter.clearTimeout(this.delayedWills[client.id]);
                            delete this.delayedWills[client.id];
                            this.adapter.log.debug(`Client [${client.id}] reconnected, its delayed will is dropped`);
                        }

                        if (options.will) {
                            // the client's will message options. object that supports the following properties:
                            // topic:   the will topic. string
                            // payload: the will payload. string
                            // qos:     will qos level. number
                            // retain:  will retain a flag. boolean
                            client._will = JSON.parse(JSON.stringify(options.will));
                            client._willDelayInterval =
                                client.protocolVersion === 5 ? (options.will.properties?.willDelayInterval ?? 0) : 0;
                            let id;
                            if (this.topic2id[client._will.topic]) {
                                id =
                                    this.topic2id[client._will.topic].id ||
                                    convertTopic2id(
                                        client._will.topic,
                                        false,
                                        this.config.prefix,
                                        this.adapter.namespace,
                                        this.config.dotToUnderscore,
                                    );
                            } else {
                                id = convertTopic2id(
                                    client._will.topic,
                                    false,
                                    this.config.prefix,
                                    this.adapter.namespace,
                                    this.config.dotToUnderscore,
                                );
                            }
                            this.checkObject(id, client._will.topic, options.will.payload)
                                .then(() => {
                                    // something went wrong while JSON.parse, so the payload of last will not be handled correctly as buffer
                                    client._will.payload = options.will!.payload;
                                    this.adapter.log.debug(
                                        `Client [${client.id}] with last will ${JSON.stringify(client._will)}`,
                                    );
                                })
                                .catch(err => this.adapter.log.info(err.message));
                        }

                        // Send all subscribed variables to a client
                        if (this.config.publishAllOnStart) {
                            // Give to client 2 seconds to send the `subscribe` message
                            client._sendOnStart = setTimeout(() => {
                                client._sendOnStart = null;
                                this.sendStates2Client(client, Object.keys(this.states));
                            }, this.config.sendOnStartInterval);
                        }

                        if (this.persistentSessions[client.id]) {
                            client._subsID = this.persistentSessions[client.id]._subsID;
                            client._subs = this.persistentSessions[client.id]._subs;
                            if (this.persistentSessions[client.id]._messages.length) {
                                // Reset retry counters immediately so that checkResends() does not
                                // see stale counts and disconnect the freshly reconnected client
                                // during the 100 ms window before resendMessages2Client() runs.
                                const now = Date.now();
                                for (const msg of this.persistentSessions[client.id]._messages) {
                                    msg.count = 0;
                                    msg.ts = now;
                                }
                                // give to the client a little bit time
                                client._resendonStart = setTimeout(
                                    (clientId: string): void => {
                                        client._resendonStart = null;
                                        if (this.persistentSessions[clientId]) {
                                            this.resendMessages2Client(
                                                client,
                                                this.persistentSessions[clientId]._messages,
                                            );
                                        }
                                    },
                                    100,
                                    client.id,
                                );
                            }
                        }

                        // set timeout for stream to 1,5 times keepalive [MQTT-3.1.2-24].
                        if (!ws && client._keepalive !== 0) {
                            const streamTimeoutSec = 1.5 * client._keepalive;
                            stream.setTimeout(streamTimeoutSec * 1000);

                            this.adapter.log.debug(
                                `Client [${client.id}] with keepalive ${client._keepalive} set timeout to ${streamTimeoutSec} seconds`,
                            );
                        }
                    };

                    // MQTT 5 enhanced authentication: the client names a method instead of sending
                    // its password, and the exchange runs over AUTH packets (MQTT-5.0 4.12).
                    const authMethod = options.properties?.authenticationMethod;
                    if (authMethod) {
                        if (!this.config.user || authMethod !== SCRAM_SHA_256) {
                            this.adapter.log.warn(
                                `Client [${client.id}] asked for the unsupported authentication method "${authMethod}"`,
                            );
                            client.connack({ reasonCode: 0x8c }); // bad authentication method
                            client.close();
                            return;
                        }

                        client._authMethod = authMethod;
                        client._completeConnect = completeConnect;
                        this.startScram(client, options.properties?.authenticationData);
                        return;
                    }

                    if (this.config.user) {
                        if (
                            this.config.user !== options.username ||
                            this.config.pass !== (options.password || '').toString()
                        ) {
                            // never log the credentials themselves
                            this.adapter.log.warn(
                                `Client [${client.id}] has invalid credentials for user "${options.username ?? ''}"`,
                            );
                            client.authenticated = false;
                            client.connack({ returnCode: 4 });
                            if (oldClient) {
                                // delete existing client
                                delete this.clients[client.id];
                                this.updateClients();
                                oldClient.destroy();
                            }
                            client.close();
                            return;
                        }
                        client.authenticated = true;
                    }

                    completeConnect();
                },
            );

            // only when we are the RECEIVER of the message
            client.on(
                'publish',
                async (packet: {
                    messageId: number;
                    qos: 0 | 1 | 2;
                    ts: number;
                    cmd: 'pubrel';
                    count: number;
                    topic: string;
                    payload: string;
                    retain: boolean;
                    properties?: { topicAlias?: number; messageExpiryInterval?: number };
                }): Promise<void> => {
                    if (!this.validateRequest('publish', client)) {
                        return;
                    }

                    if (!this.resolveTopicAlias(client, packet)) {
                        return;
                    }

                    if (this.config.debug) {
                        this.adapter.log.debug(
                            `Client [${client.id}] received publish package ${JSON.stringify(packet)}`,
                        );
                    }

                    if (this.persistentSessions[client.id]) {
                        this.persistentSessions[client.id].lastSeen = Date.now();
                    }

                    if (packet.qos === 1) {
                        // send PUBACK to a client
                        client.puback({ messageId: packet.messageId });
                    } else if (packet.qos === 2) {
                        const pack = client._messages?.find(e => e.messageId === packet.messageId);
                        if (pack) {
                            // duplicate message => ignore
                            this.adapter.log.info(
                                `Client [${client.id}] Ignored duplicate message with ID: ${packet.messageId}`,
                            );
                            return;
                        }
                        packet.ts = Date.now();
                        packet.cmd = 'pubrel';
                        packet.count = 0;
                        client._messages ||= [];
                        client._messages.push(packet);

                        client.pubrec({ messageId: packet.messageId });
                        return;
                    }

                    await this.receivedTopic(packet, client);
                },
            );

            // response for QoS2
            // only when we are the SENDER of the message
            client.on(
                'pubrec',
                (packet: {
                    messageId: number;
                    topic: MqttTopic;
                    payload: string | Buffer;
                    qos: 0 | 1 | 2;
                    retain: boolean;
                }) => {
                    if (!this.validateRequest('pubrec', client)) {
                        return;
                    }

                    if (this.config.debug) {
                        this.adapter.log.debug(
                            `Client [${client.id}] received pubrec package ${JSON.stringify(packet)}`,
                        );
                    }

                    if (this.persistentSessions[client.id]) {
                        this.persistentSessions[client.id].lastSeen = Date.now();
                    }

                    // remove this message from queue
                    const frame = client._messages?.find(e => e.messageId === packet.messageId);
                    if (frame) {
                        client.pubrel({ messageId: packet.messageId });
                    } else {
                        // The message is not in our queue anymore (e.g. purged after exceeding the
                        // retransmitted limit, or a late/duplicate pubrec). Some devices use a hardcoded
                        // QoS 2 and keep resending pubrec forever until they get a pubrel, which blocks
                        // the whole session. Send pubrel anyway to let the client complete the handshake.
                        this.adapter.log.info(
                            `Client [${client.id}] Received pubrec on ${client.id} for unknown messageId ${packet.messageId} - sending pubrel anyway to complete the QoS 2 handshake`,
                        );
                        try {
                            client.pubrel({ messageId: packet.messageId });
                        } catch (e) {
                            this.adapter.log.warn(
                                `Client [${client.id}] Cannot send pubrel for unknown messageId ${packet.messageId}: ${e as Error}`,
                            );
                        }
                    }
                },
            );

            // response for QoS2
            // only when we are the SENDER of the message
            client.on('pubcomp', (packet: { messageId: number }): void => {
                if (!this.validateRequest('pubcomp', client)) {
                    return;
                }

                if (this.config.debug) {
                    this.adapter.log.debug(`Client [${client.id}] received pubcomp package ${JSON.stringify(packet)}`);
                }

                if (this.persistentSessions[client.id]) {
                    this.persistentSessions[client.id].lastSeen = Date.now();
                }

                let pos = -1;
                // remove this message from queue
                if (client._messages) {
                    pos = client._messages.findIndex(e => e.messageId === packet.messageId);
                }
                if (pos !== -1) {
                    client._messages.splice(pos, 1);
                    this.flushPending(client);
                } else {
                    this.adapter.log.info(
                        `Client [${client.id}] Received pubcomp for unknown message ID: ${packet.messageId}`,
                    );
                }
            });

            // response for QoS2
            // only when we are the RECEIVER of the message
            client.on('pubrel', async (packet: { messageId: number }): Promise<void> => {
                if (!this.validateRequest('pubrel', client)) {
                    return;
                }

                if (this.config.debug) {
                    this.adapter.log.debug(`Client [${client.id}] received pubrel package ${JSON.stringify(packet)}`);
                }

                if (this.persistentSessions[client.id]) {
                    this.persistentSessions[client.id].lastSeen = Date.now();
                }

                // remove this message from queue
                let pos = -1;
                // remove this message from queue
                if (client._messages) {
                    pos = client._messages.findIndex(e => e.messageId === packet.messageId);
                }
                if (pos !== -1) {
                    client.pubcomp({ messageId: packet.messageId });
                    await this.receivedTopic(client._messages[pos], client);
                    client._messages.splice(pos, 1);
                } else {
                    this.adapter.log.info(
                        `Client [${client.id}] Received pubrel for unknown message ID: ${packet.messageId}`,
                    );
                }
            });

            // response for QoS1
            client.on('puback', (packet: { messageId: number }): void => {
                if (!this.validateRequest('puback', client)) {
                    return;
                }

                if (this.config.debug) {
                    this.adapter.log.debug(`Client [${client.id}] received puback package ${JSON.stringify(packet)}`);
                }

                if (this.persistentSessions[client.id]) {
                    this.persistentSessions[client.id].lastSeen = Date.now();
                }

                // remove this message from queue
                let pos = -1;
                // remove this message from queue
                if (client._messages) {
                    pos = client._messages.findIndex(e => e.messageId === packet.messageId);
                }
                if (pos !== -1) {
                    this.adapter.log.debug(
                        `Client [${client.id}] Received puback for ${client.id} message ID: ${packet.messageId}`,
                    );
                    client._messages.splice(pos, 1);
                    this.flushPending(client);
                } else {
                    this.adapter.log.info(
                        `Client [${client.id}] Received puback for unknown message ID: ${packet.messageId}`,
                    );
                }
            });

            client.on(
                'subscribe',
                async (packet: {
                    messageId: number;
                    subscriptions: { qos: 0 | 1 | 2; topic: MqttTopic; nl?: boolean; rap?: boolean; rh?: 0 | 1 | 2 }[];
                    properties?: { subscriptionIdentifier?: number };
                }): Promise<void> => {
                    if (!this.validateRequest('subscribe', client)) {
                        return;
                    }

                    if (this.config.debug) {
                        this.adapter.log.debug(
                            `Client [${client.id}] received subscribe package ${JSON.stringify(packet)}`,
                        );
                    }

                    if (this.persistentSessions[client.id]) {
                        this.persistentSessions[client.id].lastSeen = Date.now();
                    }

                    const granted: number[] = [];
                    client._subsID ||= {};
                    client._subs ||= {};

                    for (let i = 0; i < packet.subscriptions.length; i++) {
                        this.adapter.log.debug(
                            `Client [${client.id}] Handle subscribe: ${JSON.stringify(packet.subscriptions[i])}`,
                        );
                        granted.push(packet.subscriptions[i].qos);

                        // MQTT 5 subscription options; undefined for MQTT 3.1.1 clients
                        const { nl, rap, rh } = packet.subscriptions[i];
                        // one identifier applies to every subscription of this SUBSCRIBE packet
                        const subscriptionIdentifier = packet.properties?.subscriptionIdentifier;

                        // "$share/<name>/<filter>" makes this one member of a group that shares the
                        // messages. Everything below works on the plain filter; only the delivery
                        // differs (MQTT-5.0 4.8.2).
                        const { shareName, filter } = parseSharedTopic(packet.subscriptions[i].topic);

                        // "No Local" is not allowed on a shared subscription (MQTT-5.0 3.8.3.1)
                        if (shareName && nl) {
                            this.adapter.log.warn(
                                `Client [${client.id}] used "No Local" on the shared subscription "${packet.subscriptions[i].topic}"`,
                            );
                            client.disconnect({ reasonCode: 0x82 }); // protocol error
                            client.close();
                            return;
                        }

                        // Retain Handling 2 means the client does not want the value it already
                        // missed, only what is published from now on. A shared subscription never
                        // gets the stored value on subscribe either.
                        const sendKnownValue = this.config.publishOnSubscribe && rh !== 2 && !shareName;

                        if (shareName) {
                            const sharePattern = this.sharedPatternFor(filter);
                            this.joinSharedGroup(
                                shareName,
                                sharePattern,
                                new RegExp(pattern2RegEx(sharePattern, this.adapter, this.config.prefix)),
                                client.id,
                            );
                        }

                        const topic = filter;
                        let id;

                        if (this.topic2id[topic]) {
                            id =
                                this.topic2id[topic].id ||
                                convertTopic2id(
                                    topic,
                                    false,
                                    this.config.prefix,
                                    this.adapter.namespace,
                                    this.config.dotToUnderscore,
                                );
                        } else {
                            id = convertTopic2id(
                                topic,
                                false,
                                this.config.prefix,
                                this.adapter.namespace,
                                this.config.dotToUnderscore,
                            );
                        }

                        if (!id) {
                            this.adapter.log.error(`Client [${client.id}] Invalid topic: ${topic}`);
                            continue;
                        }

                        // if pattern without wildcards
                        if (!id.includes('*') && !id.includes('#') && !id.includes('+')) {
                            // Resolve the topic to a valid id (create the object if needed);
                            // otherwise reject this subscription with a SUBACK failure code (0x80)
                            // and keep processing the remaining subscriptions.
                            if (!this.topic2id[topic]?.id) {
                                try {
                                    await this.checkObject(id, topic);
                                } catch {
                                    granted[i] = 0x80;
                                    continue;
                                }
                            }

                            if (!this.topic2id[topic]?.id) {
                                granted[i] = 0x80;
                                continue;
                            }

                            const exactRegex = new RegExp(pattern2RegEx(id, this.adapter, this.config.prefix));
                            client._subsID[this.topic2id[topic].id] = {
                                pattern: id,
                                regex: exactRegex,
                                qos: packet.subscriptions[i].qos,
                                nl,
                                rap,
                                rh,
                                subscriptionIdentifier,
                                shareName,
                            };

                            this.adapter.log.info(`Client [${client.id}] subscribes on "${this.topic2id[topic].id}"`);

                            if (sendKnownValue) {
                                setTimeout(() => {
                                    this.adapter.log.info(`Client [${client.id}] publishOnSubscribe`);
                                    this.sendState2Client(
                                        client,
                                        this.topic2id[topic].id,
                                        this.states[this.topic2id[topic].id],
                                        undefined,
                                        !this.config.noRetain,
                                        undefined,
                                        'retained',
                                    );
                                }, 200);
                            }
                        } else {
                            let pattern = topic;
                            // remove prefix
                            if (pattern.startsWith(this.config.prefix)) {
                                pattern = pattern.substring(this.config.prefix.length);
                            }
                            pattern = pattern.replace(/\//g, '.');
                            if (pattern[0] === '.') {
                                pattern = pattern.substring(1);
                            }

                            // add a simple pattern
                            let regText = pattern2RegEx(pattern, this.adapter, this.config.prefix);
                            client._subs[topic] = {
                                regex: new RegExp(regText),
                                qos: packet.subscriptions[i].qos,
                                pattern: pattern,
                                nl,
                                rap,
                                rh,
                                subscriptionIdentifier,
                                shareName,
                            };

                            this.adapter.log.info(
                                `Client [${client.id}] subscribes on "${topic}" with regex /${regText}/`,
                            );

                            // add simple mqtt.0.pattern
                            pattern = `${this.adapter.namespace}/${pattern}`;
                            regText = pattern2RegEx(pattern, this.adapter, this.config.prefix);
                            client._subs[`${this.adapter.namespace}/${topic}`] = {
                                regex: new RegExp(regText),
                                qos: packet.subscriptions[i].qos,
                                pattern,
                                nl,
                                rap,
                                rh,
                                subscriptionIdentifier,
                                shareName,
                            };
                            this.adapter.log.info(
                                `Client [${client.id}] subscribes on "${topic}"  with regex /${regText}/`,
                            );

                            if (sendKnownValue) {
                                setTimeout(() => {
                                    this.adapter.log.info(
                                        `Client [${client.id}] publishOnSubscribe send all known states`,
                                    );
                                    Object.keys(this.states).forEach(savedId => {
                                        if (this.checkPattern(client._subs!, savedId)) {
                                            this.sendState2Client(
                                                client,
                                                savedId,
                                                this.states[savedId],
                                                undefined,
                                                !this.config.noRetain,
                                                undefined,
                                                'retained',
                                            );
                                        }
                                    });
                                }, 200);
                            }
                        }
                    }

                    client.suback({ granted, messageId: packet.messageId });
                },
            );

            client.on('unsubscribe', (packet: { messageId: number; unsubscriptions: MqttTopic[] }): void => {
                if (!this.validateRequest('unsubscribe', client)) {
                    return;
                }

                if (this.config.debug) {
                    this.adapter.log.debug(
                        `Client [${client.id}] received unsubscribe package ${JSON.stringify(packet)}`,
                    );
                }

                if (this.persistentSessions[client.id]) {
                    this.persistentSessions[client.id].lastSeen = Date.now();
                }

                for (let i = 0; i < packet.unsubscriptions.length; i++) {
                    // "$share/<name>/<filter>" only leaves that group; everything below works on
                    // the plain filter again
                    const { shareName, filter } = parseSharedTopic(packet.unsubscriptions[i]);
                    const topic = filter;
                    let id;

                    if (this.topic2id[topic]) {
                        id =
                            this.topic2id[topic].id ||
                            convertTopic2id(
                                topic,
                                false,
                                this.config.prefix,
                                this.adapter.namespace,
                                this.config.dotToUnderscore,
                            );
                    } else {
                        id = convertTopic2id(
                            topic,
                            false,
                            this.config.prefix,
                            this.adapter.namespace,
                            this.config.dotToUnderscore,
                        );
                    }

                    if (!id) {
                        this.adapter.log.error(`Client [${client.id}] unsubscribes from invalid topic: ${topic}`);
                        continue;
                    }

                    if (shareName) {
                        this.leaveSharedGroups(client.id, this.sharedPatternFor(topic));
                        this.adapter.log.info(
                            `Client [${client.id}] left the shared subscription "${shareName}" for "${topic}"`,
                        );
                    }

                    // if pattern without wildcards
                    if (!id.includes('*') && !id.includes('#') && !id.includes('+')) {
                        // If the state is known
                        if (this.topic2id[topic]) {
                            const _id = this.topic2id[topic].id;
                            if (client._subsID?.[_id]) {
                                delete client._subsID[_id];
                                this.adapter.log.info(`Client [${client.id}] unsubscribes on "${_id}"`);
                            } else {
                                this.adapter.log.info(`Client [${client.id}] unsubscribes on unknown "${_id}"`);
                            }
                        } else {
                            this.adapter.log.info(`Client [${client.id}] unsubscribes on unknown topic "${topic}"`);
                        }
                    } else {
                        let pattern = topic.replace(/\//g, '.');
                        if (pattern[0] === '.') {
                            pattern = pattern.substring(1);
                        }

                        // add a simple pattern
                        if (client._subs?.[topic]) {
                            this.adapter.log.info(`Client [${client.id}] unsubscribes on "${topic}"`);
                            delete client._subs[topic];
                            if (client._subs[`${this.adapter.namespace}/${topic}`]) {
                                // add simple mqtt.0.pattern
                                delete client._subs[`${this.adapter.namespace}/${topic}`];
                                this.adapter.log.info(
                                    `Client [${client.id}] unsubscribes on "${this.adapter.namespace}/${topic}"`,
                                );
                            }
                        } else {
                            this.adapter.log.info(`Client [${client.id}] unsubscribes on unknown "${topic}"`);
                        }
                    }
                }
                // MQTT 5 wants one reason code per unsubscribed topic
                client.unsuback({ messageId: packet.messageId, count: packet.unsubscriptions.length });
            });

            // MQTT 5 enhanced authentication (MQTT-5.0 4.12): either the second half of the
            // exchange that started with the CONNECT, or a re-authentication of a client that is
            // already connected.
            client.on(
                'auth',
                (packet: {
                    reasonCode?: number;
                    properties?: { authenticationMethod?: string; authenticationData?: Buffer };
                }): void => {
                    const method = packet.properties?.authenticationMethod;

                    // The method must not change during a connection (MQTT-5.0 3.15.2.2.2)
                    if (!client._authMethod || method !== client._authMethod) {
                        this.adapter.log.warn(
                            `Client [${client.id}] sent AUTH with the wrong method "${method ?? ''}"`,
                        );
                        this.rejectAuthentication(client, !!client.authenticated);
                        return;
                    }

                    if (packet.reasonCode === 0x19) {
                        // re-authentication: only allowed once the client is through
                        if (!client.authenticated) {
                            this.rejectAuthentication(client);
                            return;
                        }
                        this.adapter.log.debug(`Client [${client.id}] re-authenticates`);
                        this.startScram(client, packet.properties?.authenticationData);
                        return;
                    }

                    if (packet.reasonCode !== 0x18) {
                        this.adapter.log.warn(
                            `Client [${client.id}] sent AUTH with the unexpected reason code ${packet.reasonCode}`,
                        );
                        this.rejectAuthentication(client, !!client.authenticated);
                        return;
                    }

                    void this.finishScram(client, packet.properties?.authenticationData, !!client.authenticated);
                },
            );

            client.on('pingreq', (/*packet*/) => {
                if (!this.validateRequest('pingreq', client)) {
                    return;
                }

                if (this.persistentSessions[client.id]) {
                    this.persistentSessions[client.id].lastSeen = Date.now();
                }

                this.adapter.log.debug(`Client [${client.id}] pingreq`);
                client.pingresp();
            });

            // connection error handling
            client.on('close', (hadError?: boolean) =>
                this.clientClose(client, hadError ? 'closed because of error' : 'closed'),
            );
            client.on('error', (e: Error) => this.clientClose(client, e.toString()));
            client.on('disconnect', () => this.clientClose(client, 'disconnected'));

            // client lost without a close
            stream.on('timeout', () => this.clientClose(client, 'timeout'));
        });

        (server || (socket as Server))
            .listen(port, bind, () => {
                this.adapter.log.info(
                    `Starting MQTT${ws ? '-WebSocket' : ''}${ssl ? ' (Secure)' : ''}${this.config.user ? ' authenticated' : ''} server on ${bind || '0.0.0.0'}:${port}`,
                );
                this.adapter.log.debug(`The MQTT server${ws ? ' (WebSocket)' : ''} has successfully started!`);
            })
            .on('error', (err: Error): void =>
                this.adapter.log.error(
                    `Error starting MQTT (Setting up listener)${ws ? '-WebSocket' : ''}${ssl ? ' (Secure)' : ''}${this.config.user ? ' authenticated' : ''} server on ${bind || '0.0.0.0'}:${port}: ${err}`,
                ),
            );
    }

    private checkResends(): void {
        const now = Date.now();
        this.resending = true;
        for (const clientId in this.clients) {
            if (Object.prototype.hasOwnProperty.call(this.clients, clientId) && this.clients[clientId]?._messages) {
                for (let m = this.clients[clientId]._messages.length - 1; m >= 0; m--) {
                    const message = this.clients[clientId]._messages[m];

                    if (message.expiresAt && message.expiresAt <= now) {
                        this.adapter.log.debug(
                            `Client [${clientId}] Message ${message.messageId} for "${message.topic}" expired, dropping it`,
                        );
                        this.clients[clientId]._messages.splice(m, 1);
                        continue;
                    }

                    if (now - message.ts! >= this.config.retransmitInterval) {
                        if (message.count! > this.config.retransmitCount) {
                            if (this.clients[clientId]._keepalive === 0) {
                                // keepalive=0 means the client disabled the keepalive mechanism,
                                // so the broker has no other way to detect a dead connection.
                                // Disconnect now to preserve the QoS guarantee: clientClose()
                                // keeps the persistent session intact so all queued messages
                                // are resent on the next reconnection.
                                this.adapter.log.warn(
                                    `Client [${clientId}] Message ${message.messageId} not acknowledged after ${message.count} retries - disconnecting client (keepalive=0)`,
                                );
                                this.clientClose(this.clients[clientId], 'unresponsive - too many retransmissions');
                                break; // _messages of this client are no longer valid after close
                            }
                            // keepalive > 0: the stream timeout (1.5 × keepalive) will close the
                            // connection if the client is truly dead, as required by MQTT §3.1.2.10.
                            // Keep retransmitting until that happens.
                            this.adapter.log.debug(
                                `Client [${clientId}] Message ${message.messageId} not acknowledged after ${message.count} retries - waiting for keepalive timeout (keepalive=${this.clients[clientId]._keepalive}s)`,
                            );
                        }

                        // resend this message
                        message.count!++;
                        message.ts = now;
                        try {
                            this.adapter.log.debug(
                                `Client [${clientId}] Resend for ${message.cmd} message topic: ${message.topic}, payload: ${message.payload}`,
                            );
                            if (message.cmd === 'publish') {
                                message.dup = true;
                                this.clients[clientId].publish(message);
                            } else if (message.cmd === 'pubrel') {
                                this.clients[clientId].pubrec({
                                    messageId: message.messageId,
                                });
                            }
                        } catch (e) {
                            this.adapter.log.warn(`Client [${clientId}] Cannot publish message: ${e as Error}`);
                        }

                        if (this.config.sendInterval) {
                            setTimeout(() => this.checkResends(), this.config.sendInterval);
                        } else {
                            setImmediate(() => this.checkResends());
                        }
                        return;
                    }
                }
            }
        }

        // delete old sessions
        if (this.config.storeClientsTime !== -1) {
            Object.keys(this.persistentSessions).forEach(id => {
                if (
                    !this.persistentSessions[id] ||
                    now - this.persistentSessions[id].lastSeen > this.config.storeClientsTime * 60000
                ) {
                    delete this.persistentSessions[id];
                }
            });
        }

        this.resending = false;
    }

    private init(): void {
        // create a connected object and state
        this.adapter.getObject('info.connection', (_err, obj) => {
            if (!obj?.common || obj.common.type !== 'string') {
                obj = {
                    _id: 'info.connection',
                    type: 'state',
                    common: {
                        role: 'info.clients',
                        name: {
                            en: 'List of connected clients',
                            de: 'Liste der verbundenen Clients',
                            ru: 'Список подключенных клиентов',
                            it: 'Elenco dei client connessi',
                            es: 'Lista de clientes conectados',
                            pt: 'Lista de clientes conectados',
                            nl: 'Lijst van verbonden clients',
                            fr: 'Liste des clients connectés',
                            pl: 'Lista podłączonych klientów',
                            uk: 'Список підключених клієнтів',
                            'zh-cn': '已连接客户端的列表',
                        },
                        type: 'string',
                        read: true,
                        write: false,
                        def: '',
                    },
                    native: {},
                };

                this.adapter.setObject('info.connection', obj, () => this.updateClients());
            } else {
                this.updateClients();
            }
        });

        this.config.port = parseInt(this.config.port as unknown as string, 10) || 1883;
        if (this.config.port < 0 || this.config.port > 65535) {
            this.adapter.log.error(`Port ${this.config.port} is invalid, using 1883.`);
            this.config.port = 1883;
        }
        this.config.retransmitInterval ||= 2000;
        this.config.retransmitCount ||= 10;
        if (this.config.storeClientsTime === undefined) {
            this.config.storeClientsTime = 1440;
        } else {
            this.config.storeClientsTime = parseInt(this.config.storeClientsTime as unknown as string, 10) || 0;
        }

        try {
            // If using MQTTs, then create a TLS server with tls.createServer(), it's better for the TLS handshake.
            // Otherwise, the server may not send MQTT-CONNACK, and protocol handling could fail.
            this.server = this.config.ssl ? createTlsServer(this.config.certificates!) : createNetServer();
        } catch (err) {
            this.adapter.log.error(`Cannot create server: ${err as Error}`);
            this.adapter.terminate
                ? this.adapter.terminate(EXIT_CODES.ADAPTER_REQUESTED_TERMINATION)
                : process.exit(EXIT_CODES.ADAPTER_REQUESTED_TERMINATION);
            return;
        }

        this.server.on('error', (err: Error): void => {
            this.adapter.log.error(`Cannot create server: ${err}`);
            this.adapter.terminate
                ? this.adapter.terminate(EXIT_CODES.ADAPTER_REQUESTED_TERMINATION)
                : process.exit(EXIT_CODES.ADAPTER_REQUESTED_TERMINATION);
        });

        try {
            this.adapter.log.debug(`The MQTT server is starting now...`);
            this.startServer(this.server, null, this.config.port, this.config.bind, this.config.ssl, false);
        } catch (err) {
            this.adapter.log.error(`Cannot create server: ${err as Error}`);
            this.adapter.terminate
                ? this.adapter.terminate(EXIT_CODES.ADAPTER_REQUESTED_TERMINATION)
                : process.exit(EXIT_CODES.ADAPTER_REQUESTED_TERMINATION);
            return;
        }
        if (this.config.webSocket) {
            this.serverForWs = this.config.ssl ? createHttpsServer(this.config.certificates!) : createHttpServer();
            this.serverWs = new WsServer({ server: this.serverForWs });

            try {
                this.adapter.log.debug(`The MQTT server (Websocket) is starting now...`);
                this.startServer(
                    this.serverWs,
                    this.serverForWs,
                    this.config.port + 1,
                    this.config.bind,
                    this.config.ssl,
                    true,
                );
            } catch (err) {
                this.adapter.log.error(`Cannot create server: ${err as Error}`);
                this.adapter.terminate
                    ? this.adapter.terminate(EXIT_CODES.ADAPTER_REQUESTED_TERMINATION)
                    : process.exit(EXIT_CODES.ADAPTER_REQUESTED_TERMINATION);
                return;
            }
        }

        this.resendTimer = setInterval(
            () => !this.resending && this.checkResends(),
            this.config.retransmitInterval || 2000,
        );
    }
}
